-- =====================================================
-- SCRIPT COMPLETO - BASE DE DATOS AEROPORTUARIA
-- CON COLUMNAS AUTOINCREMENTABLES (GENERATED BY DEFAULT AS IDENTITY)
-- ORDENADO POR DEPENDENCIAS (240 TABLAS)
-- =====================================================

-- =====================================================
-- GRUPO 1: CATÁLOGOS FUNDAMENTALES (INDEPENDIENTES)
-- =====================================================

-- =====================================================
-- MÓDULO 1: INFRAESTRUCTURA AEROPORTUARIA (8 TABLAS)
-- =====================================================

-- Tabla 1.1: aeropuertos (sin cambios, clave natural)
CREATE TABLE aeropuertos (
    codigo_aeropuerto VARCHAR2(10) PRIMARY KEY,
    nombre VARCHAR2(100) NOT NULL,
    ciudad VARCHAR2(50) NOT NULL,
    pais VARCHAR2(50) NOT NULL,
    region VARCHAR2(50),
    continente VARCHAR2(20),
    huso_horario VARCHAR2(10),
    latitud NUMBER(10,6),
    longitud NUMBER(10,6),
    elevacion_metros NUMBER,
    terminales NUMBER,
    puertas_abordaje NUMBER,
    activo NUMBER(1) DEFAULT 1 CHECK (activo IN (0,1)),
    fecha_registro DATE DEFAULT SYSDATE,
    usuario_registro VARCHAR2(50)
);

-- Tabla 1.2: tipos_aeropuerto
CREATE TABLE tipos_aeropuerto (
    id_tipo_aeropuerto NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    descripcion VARCHAR2(50) NOT NULL,
    codigo VARCHAR2(10) UNIQUE,
    activo NUMBER(1) DEFAULT 1
);

-- Tabla 1.3: aeropuertos_tipos (clave compuesta, no autoincremental)
CREATE TABLE aeropuertos_tipos (
    codigo_aeropuerto VARCHAR2(10),
    id_tipo_aeropuerto NUMBER,
    fecha_asignacion DATE DEFAULT SYSDATE,
    PRIMARY KEY (codigo_aeropuerto, id_tipo_aeropuerto),
    FOREIGN KEY (codigo_aeropuerto) REFERENCES aeropuertos(codigo_aeropuerto),
    FOREIGN KEY (id_tipo_aeropuerto) REFERENCES tipos_aeropuerto(id_tipo_aeropuerto)
);

-- Tabla 1.4: aeropuertos_contactos
CREATE TABLE aeropuertos_contactos (
    id_contacto NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    codigo_aeropuerto VARCHAR2(10),
    tipo_contacto VARCHAR2(30) CHECK (tipo_contacto IN ('ADMINISTRACION', 'OPERACIONES', 'SEGURIDAD', 'MANTENIMIENTO', 'ATENCION_CLIENTE')),
    nombre VARCHAR2(100),
    cargo VARCHAR2(50),
    telefono VARCHAR2(20),
    email VARCHAR2(100),
    horario_atencion VARCHAR2(100),
    activo NUMBER(1) DEFAULT 1,
    FOREIGN KEY (codigo_aeropuerto) REFERENCES aeropuertos(codigo_aeropuerto)
);

-- Tabla 1.5: instalaciones_aeropuerto
CREATE TABLE instalaciones_aeropuerto (
    id_instalacion NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    codigo_aeropuerto VARCHAR2(10),
    nombre_instalacion VARCHAR2(100),
    tipo_instalacion VARCHAR2(50) CHECK (tipo_instalacion IN ('TERMINAL', 'HANGAR', 'PISTA', 'TORRE_CONTROL', 'ESTACIONAMIENTO', 'COMERCIAL')),
    capacidad NUMBER,
    estado VARCHAR2(20),
    fecha_construccion DATE,
    ultima_renovacion DATE,
    FOREIGN KEY (codigo_aeropuerto) REFERENCES aeropuertos(codigo_aeropuerto)
);

-- Tabla 1.6: pistas_aterrizaje
CREATE TABLE pistas_aterrizaje (
    id_pista NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    codigo_aeropuerto VARCHAR2(10),
    numero_pista VARCHAR2(10),
    longitud_metros NUMBER,
    anchura_metros NUMBER,
    superficie VARCHAR2(30) CHECK (superficie IN ('ASFALTO', 'CONCRETO', 'HIERBA', 'GRAVA')),
    iluminacion_nocturna NUMBER(1) DEFAULT 1,
    sistema_ils NUMBER(1) DEFAULT 0,
    activo NUMBER(1) DEFAULT 1,
    FOREIGN KEY (codigo_aeropuerto) REFERENCES aeropuertos(codigo_aeropuerto)
);

-- Tabla 1.7: puertas_embarque
CREATE TABLE puertas_embarque (
    id_puerta NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    codigo_aeropuerto VARCHAR2(10),
    numero_puerta VARCHAR2(10),
    terminal VARCHAR2(10),
    tipo_puerta VARCHAR2(20) CHECK (tipo_puerta IN ('NACIONAL', 'INTERNACIONAL', 'MIXTA')),
    capacidad_maxima NUMBER,
    tiene_pasarela NUMBER(1) DEFAULT 1,
    activo NUMBER(1) DEFAULT 1,
    FOREIGN KEY (codigo_aeropuerto) REFERENCES aeropuertos(codigo_aeropuerto)
);

-- Tabla 1.8: estaciones_monitoreo_ambiental
CREATE TABLE estaciones_monitoreo_ambiental (
    id_estacion_ambiental NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    codigo_estacion VARCHAR2(20) UNIQUE NOT NULL,
    nombre_estacion VARCHAR2(100),
    ubicacion VARCHAR2(200) NOT NULL,
    coordenada_latitud NUMBER(10,6),
    coordenada_longitud NUMBER(10,6),
    tipo_estacion VARCHAR2(30) CHECK (tipo_estacion IN ('RUIDO', 'AIRE', 'AGUA', 'MULTIPROPOSITO')),
    fecha_instalacion DATE,
    fecha_ultima_calibracion DATE,
    activa NUMBER(1) DEFAULT 1,
    responsable_mantenimiento NUMBER
);

-- =====================================================
-- MÓDULO 2: FLOTA AÉREA (5 TABLAS)
-- =====================================================

-- Tabla 2.1: modelos_aviones
CREATE TABLE modelos_aviones (
    id_modelo NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre_modelo VARCHAR2(50) NOT NULL,
    fabricante VARCHAR2(50),
    capacidad_pasajeros NUMBER NOT NULL,
    capacidad_carga_kg NUMBER,
    autonomia_km NUMBER,
    velocidad_crucero_kmh NUMBER,
    longitud_metros NUMBER,
    envergadura_metros NUMBER,
    altura_metros NUMBER,
    tripulacion_minima NUMBER,
    anio_fabricacion NUMBER,
    activo NUMBER(1) DEFAULT 1
);

-- Tabla 2.2: fabricantes_aviones
CREATE TABLE fabricantes_aviones (
    id_fabricante NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre_fabricante VARCHAR2(50) NOT NULL,
    pais_origen VARCHAR2(50),
    anio_fundacion NUMBER,
    sede_principal VARCHAR2(100),
    website VARCHAR2(100),
    activo NUMBER(1) DEFAULT 1
);

-- Tabla 2.3: motores_aviones
CREATE TABLE motores_aviones (
    id_motor NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre_motor VARCHAR2(50),
    fabricante_motor VARCHAR2(50),
    tipo_motor VARCHAR2(30) CHECK (tipo_motor IN ('TURBOFAN', 'TURBOPROP', 'PISTON', 'JET')),
    empuje_libras NUMBER,
    activo NUMBER(1) DEFAULT 1
);

-- Tabla 2.4: historial_aviones
CREATE TABLE historial_aviones (
    id_historial NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    matricula_avion VARCHAR2(20),
    id_modelo NUMBER,
    fecha_registro DATE,
    evento VARCHAR2(100),
    descripcion VARCHAR2(500),
    horas_vuelo NUMBER,
    ciclos_vuelo NUMBER,
    FOREIGN KEY (id_modelo) REFERENCES modelos_aviones(id_modelo)
);

-- Tabla 2.5: mantenimiento_aviones
CREATE TABLE mantenimiento_aviones (
    id_mantenimiento NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    matricula_avion VARCHAR2(20),
    id_modelo NUMBER,
    fecha_mantenimiento DATE,
    tipo_mantenimiento VARCHAR2(50) CHECK (tipo_mantenimiento IN ('PREVENTIVO', 'CORRECTIVO', 'PREDICTIVO', 'MAYOR')),
    descripcion VARCHAR2(500),
    horas_vuelo_actuales NUMBER,
    proximo_mantenimiento DATE,
    costo NUMBER(12,2),
    taller VARCHAR2(100),
    tecnico_responsable VARCHAR2(100),
    FOREIGN KEY (id_modelo) REFERENCES modelos_aviones(id_modelo)
);

-- =====================================================
-- MÓDULO 3: AEROLÍNEAS Y OPERACIONES (7 TABLAS)
-- =====================================================

-- Tabla 3.1: aerolineas
CREATE TABLE aerolineas (
    id_aerolinea NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre_aerolinea VARCHAR2(100) NOT NULL,
    codigo_iata VARCHAR2(5),
    codigo_oaci VARCHAR2(5),
    pais_origen VARCHAR2(50),
    anio_fundacion NUMBER,
    flota_total NUMBER,
    destinos_totales NUMBER,
    alianza VARCHAR2(30) CHECK (alianza IN ('STAR_ALLIANCE', 'SKYTEAM', 'ONEWORLD', 'NINGUNA')),
    website VARCHAR2(100),
    telefono_contacto VARCHAR2(20),
    email_contacto VARCHAR2(100),
    activo NUMBER(1) DEFAULT 1,
    fecha_registro DATE DEFAULT SYSDATE
);

-- Tabla 3.2: tipos_aerolinea
CREATE TABLE tipos_aerolinea (
    id_tipo_aerolinea NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    descripcion VARCHAR2(50) CHECK (descripcion IN ('COMERCIAL', 'CARGA', 'CHARTER', 'EJECUTIVA', 'LOW_COST')),
    activo NUMBER(1) DEFAULT 1
);

-- Tabla 3.3: aerolineas_tipos (clave compuesta)
CREATE TABLE aerolineas_tipos (
    id_aerolinea NUMBER,
    id_tipo_aerolinea NUMBER,
    fecha_asignacion DATE DEFAULT SYSDATE,
    PRIMARY KEY (id_aerolinea, id_tipo_aerolinea),
    FOREIGN KEY (id_aerolinea) REFERENCES aerolineas(id_aerolinea),
    FOREIGN KEY (id_tipo_aerolinea) REFERENCES tipos_aerolinea(id_tipo_aerolinea)
);

-- Tabla 3.4: aerolineas_certificaciones
CREATE TABLE aerolineas_certificaciones (
    id_certificacion NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_aerolinea NUMBER,
    tipo_certificacion VARCHAR2(50),
    entidad_emisora VARCHAR2(100),
    fecha_emision DATE,
    fecha_expiracion DATE,
    numero_certificado VARCHAR2(50),
    activo NUMBER(1) DEFAULT 1,
    FOREIGN KEY (id_aerolinea) REFERENCES aerolineas(id_aerolinea)
);

-- Tabla 3.5: alianzas_aerolineas
CREATE TABLE alianzas_aerolineas (
    id_alianza NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre_alianza VARCHAR2(50) NOT NULL,
    fecha_fundacion DATE,
    sede VARCHAR2(100),
    numero_miembros NUMBER,
    descripcion VARCHAR2(500)
);

-- Tabla 3.6: alianzas_miembros (clave compuesta)
CREATE TABLE alianzas_miembros (
    id_alianza NUMBER,
    id_aerolinea NUMBER,
    fecha_ingreso DATE,
    estado_miembro VARCHAR2(20) DEFAULT 'ACTIVO',
    PRIMARY KEY (id_alianza, id_aerolinea),
    FOREIGN KEY (id_alianza) REFERENCES alianzas_aerolineas(id_alianza),
    FOREIGN KEY (id_aerolinea) REFERENCES aerolineas(id_aerolinea)
);

-- Tabla 3.7: franquicias_equipaje
CREATE TABLE franquicias_equipaje (
    id_franquicia NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_aerolinea NUMBER,
    clase_servicio VARCHAR2(20),
    peso_maximo_kg NUMBER,
    piezas_permitidas NUMBER,
    dimensiones_maximas_cm VARCHAR2(50),
    exceso_equipaje_costo NUMBER,
    moneda VARCHAR2(3),
    FOREIGN KEY (id_aerolinea) REFERENCES aerolineas(id_aerolinea)
);

-- =====================================================
-- MÓDULO 4: PROGRAMACIÓN DE VUELOS (7 TABLAS)
-- =====================================================

-- Tabla 4.1: programas_vuelo
CREATE TABLE programas_vuelo (
    id_programa NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    numero_vuelo VARCHAR2(10) UNIQUE NOT NULL,
    id_aerolinea NUMBER NOT NULL,
    aeropuerto_origen VARCHAR2(10) NOT NULL,
    aeropuerto_destino VARCHAR2(10) NOT NULL,
    tipo_vuelo VARCHAR2(15) CHECK (tipo_vuelo IN ('NACIONAL', 'INTERNACIONAL')),
    dias_semana VARCHAR2(20),
    frecuencia_semanal NUMBER,
    duracion_estimada_minutos NUMBER,
    distancia_km NUMBER,
    clase_servicio VARCHAR2(20) CHECK (clase_servicio IN ('ECONOMICA', 'EJECUTIVA', 'PRIMERA_CLASE', 'MIXTA')),
    activo NUMBER(1) DEFAULT 1,
    fecha_inicio DATE,
    fecha_fin DATE,
    FOREIGN KEY (id_aerolinea) REFERENCES aerolineas(id_aerolinea),
    FOREIGN KEY (aeropuerto_origen) REFERENCES aeropuertos(codigo_aeropuerto),
    FOREIGN KEY (aeropuerto_destino) REFERENCES aeropuertos(codigo_aeropuerto)
);

-- Tabla 4.2: dias_operacion
CREATE TABLE dias_operacion (
    id_dia NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre_dia VARCHAR2(10) NOT NULL,
    numero_dia NUMBER CHECK (numero_dia BETWEEN 1 AND 7),
    activo NUMBER(1) DEFAULT 1
);

-- Tabla 4.3: programa_dias (clave compuesta)
CREATE TABLE programa_dias (
    id_programa NUMBER,
    id_dia NUMBER,
    hora_salida_programada TIMESTAMP,
    hora_llegada_programada TIMESTAMP,
    PRIMARY KEY (id_programa, id_dia),
    FOREIGN KEY (id_programa) REFERENCES programas_vuelo(id_programa),
    FOREIGN KEY (id_dia) REFERENCES dias_operacion(id_dia)
);

-- Tabla 4.4: rutas_alternativas
CREATE TABLE rutas_alternativas (
    id_ruta_alternativa NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_programa NUMBER,
    aeropuerto_origen_alt VARCHAR2(10),
    aeropuerto_destino_alt VARCHAR2(10),
    motivo VARCHAR2(200),
    activa NUMBER(1) DEFAULT 1,
    fecha_inicio DATE,
    fecha_fin DATE,
    FOREIGN KEY (id_programa) REFERENCES programas_vuelo(id_programa),
    FOREIGN KEY (aeropuerto_origen_alt) REFERENCES aeropuertos(codigo_aeropuerto),
    FOREIGN KEY (aeropuerto_destino_alt) REFERENCES aeropuertos(codigo_aeropuerto)
);

-- Tabla 4.5: temporadas_vuelo
CREATE TABLE temporadas_vuelo (
    id_temporada NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre_temporada VARCHAR2(50),
    fecha_inicio DATE,
    fecha_fin DATE,
    factor_demanda NUMBER(3,2) CHECK (factor_demanda BETWEEN 0.5 AND 2.0),
    activa NUMBER(1) DEFAULT 1
);

-- Tabla 4.6: programas_temporada (clave compuesta)
CREATE TABLE programas_temporada (
    id_programa NUMBER,
    id_temporada NUMBER,
    ajuste_frecuencia NUMBER,
    ajuste_precio NUMBER(5,2),
    PRIMARY KEY (id_programa, id_temporada),
    FOREIGN KEY (id_programa) REFERENCES programas_vuelo(id_programa),
    FOREIGN KEY (id_temporada) REFERENCES temporadas_vuelo(id_temporada)
);

-- Tabla 4.7: restricciones_vuelo
CREATE TABLE restricciones_vuelo (
    id_restriccion NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_programa NUMBER,
    tipo_restriccion VARCHAR2(50) CHECK (tipo_restriccion IN ('CLIMATICA', 'POLITICA', 'SEGURIDAD', 'TECNICA')),
    descripcion VARCHAR2(500),
    fecha_inicio DATE,
    fecha_fin DATE,
    activa NUMBER(1) DEFAULT 1,
    FOREIGN KEY (id_programa) REFERENCES programas_vuelo(id_programa)
);

-- =====================================================
-- MÓDULO 6: TRIPULACIÓN (PRIMERA PARTE - INDEPENDIENTE)
-- =====================================================

-- Tabla 6.1: tripulacion
CREATE TABLE tripulacion (
    id_tripulante NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombres VARCHAR2(100),
    apellidos VARCHAR2(100),
    tipo_documento VARCHAR2(20),
    numero_documento VARCHAR2(30) UNIQUE,
    fecha_nacimiento DATE,
    nacionalidad VARCHAR2(50),
    tipo_tripulante VARCHAR2(30) CHECK (tipo_tripulante IN ('PILOTO', 'COPILOTO', 'SOBRECARGO', 'INGENIERO', 'AUXILIAR')),
    licencia VARCHAR2(50),
    fecha_licencia DATE,
    fecha_vencimiento_licencia DATE,
    horas_vuelo_acumuladas NUMBER,
    activo NUMBER(1) DEFAULT 1
);

-- Tabla 6.3: tripulacion_certificaciones
CREATE TABLE tripulacion_certificaciones (
    id_certificacion NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_tripulante NUMBER,
    tipo_certificacion VARCHAR2(50),
    fecha_obtencion DATE,
    fecha_vencimiento DATE,
    entidad_certificadora VARCHAR2(100),
    activa NUMBER(1) DEFAULT 1,
    FOREIGN KEY (id_tripulante) REFERENCES tripulacion(id_tripulante)
);

-- Tabla 6.4: tripulacion_disponibilidad
CREATE TABLE tripulacion_disponibilidad (
    id_disponibilidad NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_tripulante NUMBER,
    fecha_inicio DATE,
    fecha_fin DATE,
    horas_maximas_diarias NUMBER,
    disponible NUMBER(1) DEFAULT 1,
    observaciones VARCHAR2(200),
    FOREIGN KEY (id_tripulante) REFERENCES tripulacion(id_tripulante)
);

-- =====================================================
-- MÓDULO 7: PASAJEROS (10 TABLAS)
-- =====================================================

-- Tabla 7.1: pasajeros
CREATE TABLE pasajeros (
    id_pasajero NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombres VARCHAR2(100) NOT NULL,
    apellidos VARCHAR2(100) NOT NULL,
    tipo_documento VARCHAR2(20) CHECK (tipo_documento IN ('DPI', 'PASAPORTE', 'OTRO')),
    numero_documento VARCHAR2(30) UNIQUE NOT NULL,
    nacionalidad VARCHAR2(50),
    fecha_nacimiento DATE,
    genero VARCHAR2(1) CHECK (genero IN ('M', 'F', 'O')),
    telefono VARCHAR2(20),
    email VARCHAR2(100),
    direccion VARCHAR2(200),
    ciudad_residencia VARCHAR2(50),
    pais_residencia VARCHAR2(50),
    codigo_postal VARCHAR2(10),
    ocupacion VARCHAR2(100),
    estado_civil VARCHAR2(20),
    fecha_registro DATE DEFAULT SYSDATE,
    usuario_registro VARCHAR2(50)
);

-- Tabla 7.2: pasajeros_documentos
CREATE TABLE pasajeros_documentos (
    id_documento NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_pasajero NUMBER,
    tipo_documento VARCHAR2(30),
    numero_documento VARCHAR2(30),
    pais_emision VARCHAR2(50),
    fecha_emision DATE,
    fecha_expiracion DATE,
    imagen_documento BLOB,
    verificado NUMBER(1) DEFAULT 0,
    FOREIGN KEY (id_pasajero) REFERENCES pasajeros(id_pasajero)
);

-- Tabla 7.3: perfiles_viajero
CREATE TABLE perfiles_viajero (
    id_perfil NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_pasajero NUMBER,
    tipo_perfil VARCHAR2(30) CHECK (tipo_perfil IN ('FRECUENTE', 'OCASIONAL', 'VIP', 'CORPORATIVO')),
    numero_programa VARCHAR2(30),
    aerolinea_asociada NUMBER,
    puntos_acumulados NUMBER DEFAULT 0,
    categoria VARCHAR2(30),
    fecha_ingreso DATE,
    fecha_ultima_actividad DATE,
    FOREIGN KEY (id_pasajero) REFERENCES pasajeros(id_pasajero),
    FOREIGN KEY (aerolinea_asociada) REFERENCES aerolineas(id_aerolinea)
);

-- Tabla 7.4: pasajeros_preferencias
CREATE TABLE pasajeros_preferencias (
    id_preferencia NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_pasajero NUMBER,
    tipo_preferencia VARCHAR2(50) CHECK (tipo_preferencia IN ('COMIDA', 'ASIENTO', 'SERVICIOS', 'ATENCION')),
    descripcion VARCHAR2(200),
    activo NUMBER(1) DEFAULT 1,
    fecha_actualizacion DATE,
    FOREIGN KEY (id_pasajero) REFERENCES pasajeros(id_pasajero)
);

-- Tabla 7.5: pasajeros_historial_medico
CREATE TABLE pasajeros_historial_medico (
    id_historial_medico NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_pasajero NUMBER,
    condicion_medica VARCHAR2(100),
    requiere_atencion_especial NUMBER(1) DEFAULT 0,
    medicamentos_autorizados VARCHAR2(500),
    contacto_emergencia_nombre VARCHAR2(100),
    contacto_emergencia_telefono VARCHAR2(20),
    contacto_emergencia_relacion VARCHAR2(30),
    ultima_actualizacion DATE,
    FOREIGN KEY (id_pasajero) REFERENCES pasajeros(id_pasajero)
);

-- Tabla 7.8: historial_comunicaciones
CREATE TABLE historial_comunicaciones (
    id_comunicacion NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_pasajero NUMBER,
    tipo_comunicacion VARCHAR2(30) CHECK (tipo_comunicacion IN ('EMAIL', 'SMS', 'WHATSAPP', 'LLAMADA')),
    fecha_envio TIMESTAMP,
    asunto VARCHAR2(200),
    contenido VARCHAR2(2000),
    estado VARCHAR2(20) CHECK (estado IN ('ENVIADO', 'ENTREGADO', 'LEIDO')),
    respuesta_recibida NUMBER(1) DEFAULT 0,
    FOREIGN KEY (id_pasajero) REFERENCES pasajeros(id_pasajero)
);

-- Tabla 7.9: preferencias_idiomas
CREATE TABLE preferencias_idiomas (
    id_preferencia_idioma NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_pasajero NUMBER,
    idioma VARCHAR2(30),
    nivel VARCHAR2(20) CHECK (nivel IN ('NATIVO', 'AVANZADO', 'BASICO')),
    preferido NUMBER(1) DEFAULT 0,
    FOREIGN KEY (id_pasajero) REFERENCES pasajeros(id_pasajero)
);

-- Tabla 7.10: acompanantes_viaje
CREATE TABLE acompanantes_viaje (
    id_acompanante NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_pasajero_principal NUMBER,
    id_pasajero_acompanante NUMBER,
    frecuencia NUMBER,
    relacion VARCHAR2(30) CHECK (relacion IN ('FAMILIAR', 'AMIGO', 'COLEGA')),
    ultimo_viaje_juntos DATE,
    FOREIGN KEY (id_pasajero_principal) REFERENCES pasajeros(id_pasajero),
    FOREIGN KEY (id_pasajero_acompanante) REFERENCES pasajeros(id_pasajero)
);

-- Tabla 7.7: pasajeros_redes_sociales
CREATE TABLE pasajeros_redes_sociales (
    id_red_social NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_pasajero NUMBER,
    red_social VARCHAR2(30) CHECK (red_social IN ('FACEBOOK', 'TWITTER', 'INSTAGRAM', 'LINKEDIN')),
    usuario VARCHAR2(100),
    url_perfil VARCHAR2(200),
    publico NUMBER(1) DEFAULT 0,
    FOREIGN KEY (id_pasajero) REFERENCES pasajeros(id_pasajero)
);

-- =====================================================
-- MÓDULO 15: RECURSOS HUMANOS (10 TABLAS)
-- =====================================================

-- Tabla 15.1: empleados
CREATE TABLE empleados (
    id_empleado NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    codigo_empleado VARCHAR2(20) UNIQUE,
    nombres VARCHAR2(100),
    apellidos VARCHAR2(100),
    tipo_documento VARCHAR2(20),
    numero_documento VARCHAR2(30) UNIQUE,
    fecha_nacimiento DATE,
    nacionalidad VARCHAR2(50),
    genero VARCHAR2(1) CHECK (genero IN ('M', 'F', 'O')),
    direccion VARCHAR2(200),
    telefono VARCHAR2(20),
    email VARCHAR2(100),
    fecha_contratacion DATE,
    departamento VARCHAR2(50),
    cargo VARCHAR2(100),
    salario_base NUMBER(10,2),
    tipo_contrato VARCHAR2(30) CHECK (tipo_contrato IN ('PERMANENTE', 'TEMPORAL', 'PRACTICAS', 'CONSULTOR')),
    activo NUMBER(1) DEFAULT 1,
    foto_empleado BLOB
);

-- Tabla 15.2: departamentos
CREATE TABLE departamentos (
    id_departamento NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre_departamento VARCHAR2(50),
    descripcion VARCHAR2(200),
    ubicacion VARCHAR2(100),
    presupuesto_anual NUMBER(12,2),
    gerente_id NUMBER,
    activo NUMBER(1) DEFAULT 1,
    FOREIGN KEY (gerente_id) REFERENCES empleados(id_empleado)
);

-- Tabla 15.3: puestos_trabajo
CREATE TABLE puestos_trabajo (
    id_puesto NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre_puesto VARCHAR2(100),
    id_departamento NUMBER,
    nivel_jerarquico NUMBER,
    salario_minimo NUMBER(10,2),
    salario_maximo NUMBER(10,2),
    descripcion_funciones VARCHAR2(1000),
    requisitos VARCHAR2(500),
    activo NUMBER(1) DEFAULT 1,
    FOREIGN KEY (id_departamento) REFERENCES departamentos(id_departamento)
);

-- Tabla 15.4: empleados_historial
CREATE TABLE empleados_historial (
    id_historial_empleado NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_empleado NUMBER,
    fecha_cambio DATE,
    campo_modificado VARCHAR2(50),
    valor_anterior VARCHAR2(500),
    valor_nuevo VARCHAR2(500),
    motivo VARCHAR2(200),
    modificado_por NUMBER,
    FOREIGN KEY (id_empleado) REFERENCES empleados(id_empleado),
    FOREIGN KEY (modificado_por) REFERENCES empleados(id_empleado)
);

-- Tabla 15.5: asistencias
CREATE TABLE asistencias (
    id_asistencia NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_empleado NUMBER,
    fecha DATE,
    hora_entrada TIMESTAMP,
    hora_salida TIMESTAMP,
    horas_trabajadas NUMBER,
    tipo_jornada VARCHAR2(20) CHECK (tipo_jornada IN ('ORDINARIA', 'EXTRA', 'NOCTURNA', 'FESTIVO')),
    observaciones VARCHAR2(200),
    registrado_por NUMBER,
    FOREIGN KEY (id_empleado) REFERENCES empleados(id_empleado),
    FOREIGN KEY (registrado_por) REFERENCES empleados(id_empleado)
);

-- Tabla 15.6: vacaciones_permisos
CREATE TABLE vacaciones_permisos (
    id_solicitud NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_empleado NUMBER,
    tipo_solicitud VARCHAR2(30) CHECK (tipo_solicitud IN ('VACACIONES', 'PERMISO', 'LICENCIA', 'INCAPACIDAD')),
    fecha_inicio DATE,
    fecha_fin DATE,
    dias_solicitados NUMBER,
    motivo VARCHAR2(500),
    fecha_solicitud DATE,
    estado VARCHAR2(20) DEFAULT 'PENDIENTE',
    autorizado_por NUMBER,
    fecha_autorizacion DATE,
    observaciones VARCHAR2(500),
    FOREIGN KEY (id_empleado) REFERENCES empleados(id_empleado),
    FOREIGN KEY (autorizado_por) REFERENCES empleados(id_empleado)
);

-- Tabla 15.7: evaluaciones_desempeno
CREATE TABLE evaluaciones_desempeno (
    id_evaluacion NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_empleado NUMBER,
    fecha_evaluacion DATE,
    evaluador_id NUMBER,
    periodo_evaluado VARCHAR2(30),
    puntuacion_total NUMBER(5,2),
    puntuacion_productividad NUMBER(5,2),
    puntuacion_calidad NUMBER(5,2),
    puntuacion_asistencia NUMBER(5,2),
    puntuacion_trabajo_equipo NUMBER(5,2),
    comentarios VARCHAR2(1000),
    metas_futuras VARCHAR2(500),
    FOREIGN KEY (id_empleado) REFERENCES empleados(id_empleado),
    FOREIGN KEY (evaluador_id) REFERENCES empleados(id_empleado)
);

-- Tabla 15.8: capacitaciones
CREATE TABLE capacitaciones (
    id_capacitacion NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre_curso VARCHAR2(200),
    descripcion VARCHAR2(500),
    tipo_capacitacion VARCHAR2(50) CHECK (tipo_capacitacion IN ('SEGURIDAD', 'TECNICA', 'ATENCION_CLIENTE', 'IDIOMAS', 'LIDERAZGO')),
    duracion_horas NUMBER,
    costo NUMBER(10,2),
    proveedor VARCHAR2(100),
    fecha_inicio DATE,
    fecha_fin DATE,
    activo NUMBER(1) DEFAULT 1
);

-- Tabla 15.9: empleados_capacitacion (clave compuesta)
CREATE TABLE empleados_capacitacion (
    id_empleado NUMBER,
    id_capacitacion NUMBER,
    fecha_asignacion DATE,
    estado VARCHAR2(20) DEFAULT 'INSCRITO',
    fecha_completado DATE,
    calificacion NUMBER(5,2),
    certificado_obtenido NUMBER(1) DEFAULT 0,
    PRIMARY KEY (id_empleado, id_capacitacion),
    FOREIGN KEY (id_empleado) REFERENCES empleados(id_empleado),
    FOREIGN KEY (id_capacitacion) REFERENCES capacitaciones(id_capacitacion)
);

-- Tabla 15.10: uniformes_equipamiento
CREATE TABLE uniformes_equipamiento (
    id_asignacion NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_empleado NUMBER,
    tipo_equipo VARCHAR2(50) CHECK (tipo_equipo IN ('UNIFORME', 'RADIO', 'COMPUTADORA', 'HERRAMIENTA', 'CHALECO')),
    descripcion VARCHAR2(200),
    talla VARCHAR2(10),
    fecha_asignacion DATE,
    fecha_devolucion DATE,
    estado VARCHAR2(20) CHECK (estado IN ('NUEVO', 'BUENO', 'REGULAR', 'MALO')),
    observaciones VARCHAR2(200),
    FOREIGN KEY (id_empleado) REFERENCES empleados(id_empleado)
);

-- =====================================================
-- GRUPO 2: OPERACIONES Y MOVIMIENTO
-- =====================================================

-- =====================================================
-- MÓDULO 5: OPERACIONES DE VUELO (15 TABLAS)
-- =====================================================

-- Tabla 5.1: vuelos
CREATE TABLE vuelos (
    id_vuelo NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_programa NUMBER NOT NULL,
    fecha_vuelo DATE NOT NULL,
    hora_salida_programada TIMESTAMP,
    hora_llegada_programada TIMESTAMP,
    hora_salida_real TIMESTAMP,
    hora_llegada_real TIMESTAMP,
    id_modelo_avion NUMBER NOT NULL,
    matricula_avion VARCHAR2(20),
    plazas_vacias NUMBER DEFAULT 0,
    plazas_ocupadas NUMBER DEFAULT 0,
    carga_kg NUMBER DEFAULT 0,
    combustible_litros NUMBER,
    estado_vuelo VARCHAR2(20) DEFAULT 'PROGRAMADO' CHECK (estado_vuelo IN ('PROGRAMADO', 'EN_VUELO', 'ATERRIZADO', 'CANCELADO', 'REPROGRAMADO', 'DEMORADO', 'DESVIADO')),
    motivo_cancelacion VARCHAR2(500),
    fecha_reprogramado DATE,
    id_puerta_salida NUMBER,
    id_puerta_llegada NUMBER,
    observaciones_operativas VARCHAR2(1000),
    FOREIGN KEY (id_programa) REFERENCES programas_vuelo(id_programa),
    FOREIGN KEY (id_modelo_avion) REFERENCES modelos_aviones(id_modelo),
    FOREIGN KEY (id_puerta_salida) REFERENCES puertas_embarque(id_puerta),
    FOREIGN KEY (id_puerta_llegada) REFERENCES puertas_embarque(id_puerta)
);

-- Tabla 5.2: condiciones_meteorologicas
CREATE TABLE condiciones_meteorologicas (
    id_condicion NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    codigo_aeropuerto VARCHAR2(10),
    fecha_hora TIMESTAMP,
    temperatura NUMBER,
    humedad NUMBER,
    presion_atmosferica NUMBER,
    viento_velocidad NUMBER,
    viento_direccion VARCHAR2(10),
    visibilidad_km NUMBER,
    condicion_general VARCHAR2(50),
    fenomenos_especiales VARCHAR2(200),
    FOREIGN KEY (codigo_aeropuerto) REFERENCES aeropuertos(codigo_aeropuerto)
);

-- Tabla 5.3: alertas_meteorologicas
CREATE TABLE alertas_meteorologicas (
    id_alerta NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    codigo_aeropuerto VARCHAR2(10),
    tipo_alerta VARCHAR2(50),
    nivel_alerta VARCHAR2(20),
    descripcion VARCHAR2(500),
    fecha_inicio TIMESTAMP,
    fecha_fin TIMESTAMP,
    afecta_operaciones NUMBER(1) DEFAULT 1,
    FOREIGN KEY (codigo_aeropuerto) REFERENCES aeropuertos(codigo_aeropuerto)
);

-- Tabla 5.4: escalas_tecnicas
CREATE TABLE escalas_tecnicas (
    id_escala NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_vuelo NUMBER NOT NULL,
    aeropuerto_escala VARCHAR2(10) NOT NULL,
    numero_orden NUMBER NOT NULL,
    hora_llegada TIMESTAMP,
    hora_despegue TIMESTAMP,
    tiempo_escala_minutos NUMBER,
    motivo_escala VARCHAR2(200) CHECK (motivo_escala IN ('TECNICA', 'COMBUSTIBLE', 'TRIPULACION', 'CLIMATICA', 'OTROS')),
    observaciones VARCHAR2(200),
    UNIQUE (id_vuelo, numero_orden),
    FOREIGN KEY (id_vuelo) REFERENCES vuelos(id_vuelo),
    FOREIGN KEY (aeropuerto_escala) REFERENCES aeropuertos(codigo_aeropuerto)
);

-- Tabla 5.5: escalas_servicios
CREATE TABLE escalas_servicios (
    id_servicio_escala NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_escala NUMBER,
    tipo_servicio VARCHAR2(50) CHECK (tipo_servicio IN ('COMBUSTIBLE', 'MANTENIMIENTO', 'CATERING', 'LIMPIEZA', 'TRIPULACION')),
    proveedor VARCHAR2(100),
    costo NUMBER(12,2),
    moneda VARCHAR2(3),
    fecha_servicio TIMESTAMP,
    FOREIGN KEY (id_escala) REFERENCES escalas_tecnicas(id_escala)
);

-- Tabla 5.6: incidentes_vuelo
CREATE TABLE incidentes_vuelo (
    id_incidente_vuelo NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_vuelo NUMBER,
    fecha_incidente TIMESTAMP,
    tipo_incidente VARCHAR2(50) CHECK (tipo_incidente IN ('TECNICO', 'MEDICO', 'SEGURIDAD', 'CLIMATICO', 'OPERATIVO')),
    descripcion VARCHAR2(500),
    gravedad VARCHAR2(20) CHECK (gravedad IN ('BAJA', 'MEDIA', 'ALTA', 'CRITICA')),
    acciones_tomadas VARCHAR2(500),
    reportado_por VARCHAR2(100),
    FOREIGN KEY (id_vuelo) REFERENCES vuelos(id_vuelo)
);

-- Tabla 5.7: retrasos_vuelo
CREATE TABLE retrasos_vuelo (
    id_retraso NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_vuelo NUMBER,
    minutos_retraso NUMBER,
    tipo_retraso VARCHAR2(30) CHECK (tipo_retraso IN ('CLIMATICO', 'TECNICO', 'OPERACIONAL', 'TRANSITO', 'TRIPULACION')),
    causa VARCHAR2(500),
    responsable VARCHAR2(100),
    compensacion_pasajeros NUMBER(1) DEFAULT 0,
    FOREIGN KEY (id_vuelo) REFERENCES vuelos(id_vuelo)
);

-- Tabla 5.8: cancelaciones_vuelo
CREATE TABLE cancelaciones_vuelo (
    id_cancelacion NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_vuelo NUMBER,
    fecha_cancelacion TIMESTAMP,
    motivo_principal VARCHAR2(200),
    motivo_detallado VARCHAR2(500),
    notificado_a_pasajeros NUMBER(1) DEFAULT 0,
    fecha_notificacion TIMESTAMP,
    pasajeros_reubicados NUMBER,
    costo_compensacion NUMBER(12,2),
    FOREIGN KEY (id_vuelo) REFERENCES vuelos(id_vuelo)
);

-- Tabla 5.9: desvios_vuelo
CREATE TABLE desvios_vuelo (
    id_desvio NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_vuelo NUMBER,
    aeropuerto_desvio VARCHAR2(10),
    fecha_desvio TIMESTAMP,
    motivo VARCHAR2(500),
    duracion_desvio_minutos NUMBER,
    acciones_tomadas VARCHAR2(500),
    FOREIGN KEY (id_vuelo) REFERENCES vuelos(id_vuelo),
    FOREIGN KEY (aeropuerto_desvio) REFERENCES aeropuertos(codigo_aeropuerto)
);

-- Tabla 5.10: combustible_vuelo
CREATE TABLE combustible_vuelo (
    id_combustible NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_vuelo NUMBER,
    combustible_planeado_litros NUMBER,
    combustible_real_litros NUMBER,
    combustible_extra_litros NUMBER,
    tipo_combustible VARCHAR2(20),
    proveedor VARCHAR2(100),
    costo_total NUMBER(12,2),
    fecha_carga TIMESTAMP,
    FOREIGN KEY (id_vuelo) REFERENCES vuelos(id_vuelo)
);

-- Tabla 5.11: rutas_vuelo
CREATE TABLE rutas_vuelo (
    id_ruta NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_vuelo NUMBER,
    secuencia_punto NUMBER,
    coordenada_lat NUMBER(10,6),
    coordenada_lon NUMBER(10,6),
    altitud_pies NUMBER,
    velocidad_esperada_kmh NUMBER,
    tiempo_estimado_minutos NUMBER,
    FOREIGN KEY (id_vuelo) REFERENCES vuelos(id_vuelo)
);

-- Tabla 5.12: comunicaciones_vuelo
CREATE TABLE comunicaciones_vuelo (
    id_comunicacion NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_vuelo NUMBER,
    fecha_hora TIMESTAMP,
    tipo_comunicacion VARCHAR2(30),
    origen VARCHAR2(50),
    destino VARCHAR2(50),
    mensaje VARCHAR2(1000),
    operador VARCHAR2(100),
    FOREIGN KEY (id_vuelo) REFERENCES vuelos(id_vuelo)
);

-- Tabla 5.13: autorizaciones_vuelo
CREATE TABLE autorizaciones_vuelo (
    id_autorizacion NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_vuelo NUMBER,
    tipo_autorizacion VARCHAR2(50),
    entidad_autorizante VARCHAR2(100),
    numero_autorizacion VARCHAR2(50),
    fecha_emision DATE,
    fecha_expiracion DATE,
    documento_asociado BLOB,
    activa NUMBER(1) DEFAULT 1,
    FOREIGN KEY (id_vuelo) REFERENCES vuelos(id_vuelo)
);

-- Tabla 5.14: seguros_vuelo
CREATE TABLE seguros_vuelo (
    id_seguro NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_vuelo NUMBER,
    id_aerolinea NUMBER,
    tipo_seguro VARCHAR2(50),
    poliza VARCHAR2(50),
    aseguradora VARCHAR2(100),
    cobertura_maxima NUMBER(15,2),
    fecha_inicio DATE,
    fecha_fin DATE,
    prima NUMBER(12,2),
    FOREIGN KEY (id_vuelo) REFERENCES vuelos(id_vuelo),
    FOREIGN KEY (id_aerolinea) REFERENCES aerolineas(id_aerolinea)
);

-- Tabla 5.15: estadisticas_vuelo
CREATE TABLE estadisticas_vuelo (
    id_estadistica NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_vuelo NUMBER,
    pasajeros_transportados NUMBER,
    carga_transportada_kg NUMBER,
    correo_transportado_kg NUMBER,
    factor_ocupacion NUMBER(5,2),
    ingresos_totales NUMBER(12,2),
    gastos_totales NUMBER(12,2),
    beneficio_neto NUMBER(12,2),
    puntualidad_llegada NUMBER(1) DEFAULT 1,
    FOREIGN KEY (id_vuelo) REFERENCES vuelos(id_vuelo)
);

-- =====================================================
-- MÓDULO 8: RESERVAS Y BOLETERÍA (12 TABLAS)
-- =====================================================

-- Tabla 8.1: reservas
CREATE TABLE reservas (
    id_reserva NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_vuelo NUMBER NOT NULL,
    id_pasajero NUMBER NOT NULL,
    codigo_reserva VARCHAR2(20) UNIQUE NOT NULL,
    fecha_reserva DATE DEFAULT SYSDATE,
    fecha_modificacion DATE,
    estado_reserva VARCHAR2(20) DEFAULT 'CONFIRMADA' CHECK (estado_reserva IN ('CONFIRMADA', 'PENDIENTE', 'CANCELADA', 'CHECK_IN', 'ABORDADO', 'NO_SHOW')),
    tipo_tarifa VARCHAR2(30),
    precio_pagado NUMBER(10,2),
    moneda VARCHAR2(3),
    numero_asiento VARCHAR2(10),
    clase_servicio VARCHAR2(20),
    equipaje_facturado_kg NUMBER,
    equipaje_mano_kg NUMBER,
    checkin_realizado NUMBER(1) DEFAULT 0,
    fecha_checkin TIMESTAMP,
    puerta_embarque_asignada VARCHAR2(10),
    grupo_embarque NUMBER,
    observaciones VARCHAR2(500),
    FOREIGN KEY (id_vuelo) REFERENCES vuelos(id_vuelo),
    FOREIGN KEY (id_pasajero) REFERENCES pasajeros(id_pasajero)
);

-- Tabla 8.2: historial_reservas
CREATE TABLE historial_reservas (
    id_historial_reserva NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_reserva NUMBER,
    fecha_cambio TIMESTAMP,
    campo_modificado VARCHAR2(50),
    valor_anterior VARCHAR2(500),
    valor_nuevo VARCHAR2(500),
    usuario_modificacion VARCHAR2(50),
    motivo_cambio VARCHAR2(200),
    FOREIGN KEY (id_reserva) REFERENCES reservas(id_reserva)
);

-- Tabla 8.3: metodos_pago
CREATE TABLE metodos_pago (
    id_metodo_pago NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    descripcion VARCHAR2(50),
    tipo_pago VARCHAR2(30) CHECK (tipo_pago IN ('TARJETA_CREDITO', 'TARJETA_DEBITO', 'EFECTIVO', 'TRANSFERENCIA', 'PUNTOS')),
    procesador VARCHAR2(50),
    activo NUMBER(1) DEFAULT 1
);

-- Tabla 8.4: reservas_pagos
CREATE TABLE reservas_pagos (
    id_pago NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_reserva NUMBER,
    id_metodo_pago NUMBER,
    monto NUMBER(10,2),
    moneda VARCHAR2(3),
    fecha_pago TIMESTAMP,
    codigo_transaccion VARCHAR2(50),
    estado_pago VARCHAR2(20) DEFAULT 'COMPLETADO',
    comprobante_pago BLOB,
    FOREIGN KEY (id_reserva) REFERENCES reservas(id_reserva),
    FOREIGN KEY (id_metodo_pago) REFERENCES metodos_pago(id_metodo_pago)
);

-- Tabla 8.5: facturas
CREATE TABLE facturas (
    id_factura NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_reserva NUMBER,
    numero_factura VARCHAR2(30) UNIQUE,
    fecha_emision DATE,
    subtotal NUMBER(10,2),
    impuestos NUMBER(10,2),
    total NUMBER(10,2),
    moneda VARCHAR2(3),
    datos_fiscales VARCHAR2(500),
    pdf_factura BLOB,
    FOREIGN KEY (id_reserva) REFERENCES reservas(id_reserva)
);

-- Tabla 8.6: tarifas_especiales
CREATE TABLE tarifas_especiales (
    id_tarifa NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_aerolinea NUMBER,
    nombre_tarifa VARCHAR2(50),
    descripcion VARCHAR2(200),
    condiciones VARCHAR2(500),
    descuento_porcentaje NUMBER(5,2),
    fecha_inicio DATE,
    fecha_fin DATE,
    activa NUMBER(1) DEFAULT 1,
    FOREIGN KEY (id_aerolinea) REFERENCES aerolineas(id_aerolinea)
);

-- Tabla 8.7: promociones
CREATE TABLE promociones (
    id_promocion NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    codigo_promocion VARCHAR2(30) UNIQUE,
    nombre_promocion VARCHAR2(100),
    descripcion VARCHAR2(500),
    tipo_descuento VARCHAR2(20) CHECK (tipo_descuento IN ('PORCENTAJE', 'MONTO_FIJO', '2X1', 'OTRO')),
    valor_descuento NUMBER(10,2),
    fecha_inicio DATE,
    fecha_fin DATE,
    uso_maximo NUMBER,
    usos_actuales NUMBER DEFAULT 0,
    activa NUMBER(1) DEFAULT 1
);

-- Tabla 8.8: reservas_promociones (clave compuesta)
CREATE TABLE reservas_promociones (
    id_reserva NUMBER,
    id_promocion NUMBER,
    descuento_aplicado NUMBER(10,2),
    fecha_aplicacion TIMESTAMP,
    PRIMARY KEY (id_reserva, id_promocion),
    FOREIGN KEY (id_reserva) REFERENCES reservas(id_reserva),
    FOREIGN KEY (id_promocion) REFERENCES promociones(id_promocion)
);

-- Tabla 8.9: grupos_viaje
CREATE TABLE grupos_viaje (
    id_grupo NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre_grupo VARCHAR2(100),
    tipo_grupo VARCHAR2(30) CHECK (tipo_grupo IN ('FAMILIA', 'EMPRESA', 'ESCOLAR', 'TURISTICO', 'OTROS')),
    cantidad_pasajeros NUMBER,
    contacto_responsable VARCHAR2(100),
    telefono_responsable VARCHAR2(20),
    email_responsable VARCHAR2(100),
    observaciones VARCHAR2(500)
);

-- Tabla 8.10: grupos_pasajeros (clave compuesta)
CREATE TABLE grupos_pasajeros (
    id_grupo NUMBER,
    id_pasajero NUMBER,
    fecha_asignacion DATE,
    rol_en_grupo VARCHAR2(50),
    PRIMARY KEY (id_grupo, id_pasajero),
    FOREIGN KEY (id_grupo) REFERENCES grupos_viaje(id_grupo),
    FOREIGN KEY (id_pasajero) REFERENCES pasajeros(id_pasajero)
);

-- Tabla 8.11: solicitudes_especiales
CREATE TABLE solicitudes_especiales (
    id_solicitud NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_reserva NUMBER,
    tipo_solicitud VARCHAR2(50) CHECK (tipo_solicitud IN ('COMIDA_ESPECIAL', 'ASISTENCIA', 'EQUIPAJE_ESPECIAL', 'MASCOTA', 'MENOR_NO_ACOMPANADO')),
    descripcion VARCHAR2(500),
    fecha_solicitud TIMESTAMP,
    estado_solicitud VARCHAR2(20) DEFAULT 'PENDIENTE',
    fecha_resolucion TIMESTAMP,
    resolucion VARCHAR2(500),
    FOREIGN KEY (id_reserva) REFERENCES reservas(id_reserva)
);

-- Tabla 8.12: equipaje_especial
CREATE TABLE equipaje_especial (
    id_equipaje_especial NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_reserva NUMBER,
    tipo_equipaje VARCHAR2(50) CHECK (tipo_equipaje IN ('DEPORTIVO', 'INSTRUMENTO_MUSICAL', 'MASCOTA', 'DIPLOMATICO', 'VALORES')),
    peso_kg NUMBER,
    dimensiones VARCHAR2(30),
    contenido VARCHAR2(200),
    requiere_autorizacion NUMBER(1) DEFAULT 1,
    autorizado NUMBER(1) DEFAULT 0,
    costo_adicional NUMBER(10,2),
    FOREIGN KEY (id_reserva) REFERENCES reservas(id_reserva)
);

-- =====================================================
-- MÓDULO 9: CHECK-IN Y ABORDAJE (5 TABLAS)
-- =====================================================

-- Tabla 9.1: checkin_digital
CREATE TABLE checkin_digital (
    id_checkin NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_reserva NUMBER,
    fecha_checkin TIMESTAMP,
    ip_origen VARCHAR2(50),
    dispositivo VARCHAR2(100),
    pase_abordaje_generado NUMBER(1) DEFAULT 1,
    codigo_qr BLOB,
    enviado_email NUMBER(1) DEFAULT 0,
    enviado_sms NUMBER(1) DEFAULT 0,
    FOREIGN KEY (id_reserva) REFERENCES reservas(id_reserva)
);

-- Tabla 9.2: pases_abordaje
CREATE TABLE pases_abordaje (
    id_pase_abordaje NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_reserva NUMBER,
    codigo_barras VARCHAR2(100),
    qr_code BLOB,
    fecha_generacion TIMESTAMP,
    fecha_escaneo TIMESTAMP,
    puerta_embarque VARCHAR2(10),
    grupo_embarque VARCHAR2(10),
    asiento VARCHAR2(10),
    utilizado NUMBER(1) DEFAULT 0,
    FOREIGN KEY (id_reserva) REFERENCES reservas(id_reserva)
);

-- Tabla 9.3: puertas_embarque_asignacion
CREATE TABLE puertas_embarque_asignacion (
    id_asignacion_puerta NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_puerta NUMBER,
    id_vuelo NUMBER,
    fecha_asignacion TIMESTAMP,
    hora_inicio TIMESTAMP,
    hora_fin TIMESTAMP,
    asignado_por NUMBER,
    FOREIGN KEY (id_puerta) REFERENCES puertas_embarque(id_puerta),
    FOREIGN KEY (id_vuelo) REFERENCES vuelos(id_vuelo),
    FOREIGN KEY (asignado_por) REFERENCES empleados(id_empleado)
);

-- Tabla 9.4: grupos_embarque
CREATE TABLE grupos_embarque (
    id_grupo_embarque NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_vuelo NUMBER,
    numero_grupo NUMBER,
    descripcion VARCHAR2(100),
    orden NUMBER,
    tiempo_estimado TIMESTAMP,
    FOREIGN KEY (id_vuelo) REFERENCES vuelos(id_vuelo)
);

-- Tabla 9.5: control_abordaje
CREATE TABLE control_abordaje (
    id_control_abordaje NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_vuelo NUMBER,
    id_reserva NUMBER,
    hora_abordaje TIMESTAMP,
    verificado_por NUMBER,
    estado VARCHAR2(20) CHECK (estado IN ('ABORDADO', 'NO_ABORDADO')),
    observaciones VARCHAR2(200),
    FOREIGN KEY (id_vuelo) REFERENCES vuelos(id_vuelo),
    FOREIGN KEY (id_reserva) REFERENCES reservas(id_reserva),
    FOREIGN KEY (verificado_por) REFERENCES empleados(id_empleado)
);

-- =====================================================
-- MÓDULO 18: MENORES Y GRUPOS ESPECIALES (4 TABLAS)
-- =====================================================

-- Tabla 18.1: menores_no_acompanados
CREATE TABLE menores_no_acompanados (
    id_menor NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_reserva NUMBER,
    edad NUMBER,
    nombre_entrega_origen VARCHAR2(100),
    relacion_origen VARCHAR2(50),
    telefono_origen VARCHAR2(20),
    nombre_recoge_destino VARCHAR2(100),
    relacion_destino VARCHAR2(50),
    telefono_destino VARCHAR2(20),
    observaciones VARCHAR2(500),
    FOREIGN KEY (id_reserva) REFERENCES reservas(id_reserva)
);

-- Tabla 18.2: pasajeros_menores
CREATE TABLE pasajeros_menores (
    id_relacion NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_menor NUMBER,
    id_acompanante NUMBER,
    tipo_relacion VARCHAR2(30) CHECK (tipo_relacion IN ('PADRE', 'MADRE', 'TUTOR', 'FAMILIAR')),
    autorizado NUMBER(1) DEFAULT 0,
    documento_autorizacion BLOB,
    FOREIGN KEY (id_menor) REFERENCES menores_no_acompanados(id_menor),
    FOREIGN KEY (id_acompanante) REFERENCES pasajeros(id_pasajero)
);

-- Tabla 18.3: autorizaciones_menores
CREATE TABLE autorizaciones_menores (
    id_autorizacion_menor NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_menor NUMBER,
    numero_autorizacion VARCHAR2(50),
    fecha_emision DATE,
    fecha_expiracion DATE,
    autoridad_emisora VARCHAR2(100),
    documento_autorizacion BLOB,
    verificado NUMBER(1) DEFAULT 0,
    FOREIGN KEY (id_menor) REFERENCES menores_no_acompanados(id_menor)
);

-- Tabla 18.4: pasajeros_mascotas
CREATE TABLE pasajeros_mascotas (
    id_mascota NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_pasajero NUMBER,
    id_reserva NUMBER,
    nombre_mascota VARCHAR2(50),
    tipo_mascota VARCHAR2(30) CHECK (tipo_mascota IN ('PERRO', 'GATO', 'AVE')),
    raza VARCHAR2(50),
    peso_kg NUMBER,
    certificado_salud BLOB,
    vacunas VARCHAR2(500),
    transportadora_dimensiones VARCHAR2(50),
    autorizado NUMBER(1) DEFAULT 0,
    FOREIGN KEY (id_pasajero) REFERENCES pasajeros(id_pasajero),
    FOREIGN KEY (id_reserva) REFERENCES reservas(id_reserva)
);

-- =====================================================
-- MÓDULO 19: GESTIÓN DE CARGA Y MERCANCÍAS (10 TABLAS)
-- =====================================================

-- Tabla 19.1: tipos_carga
CREATE TABLE tipos_carga (
    id_tipo_carga NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    codigo_carga VARCHAR2(10) UNIQUE,
    descripcion VARCHAR2(100) NOT NULL,
    categoria VARCHAR2(30) CHECK (categoria IN ('GENERAL', 'PERECEDERA', 'PELIGROSA', 'VALORES', 'DIPLOMATICA', 'ANIMALES_VIVOS', 'MEDICAMENTOS')),
    requiere_frio NUMBER(1) DEFAULT 0 CHECK (requiere_frio IN (0,1)),
    temperatura_requerida NUMBER(5,2),
    peligroso NUMBER(1) DEFAULT 0 CHECK (peligroso IN (0,1)),
    clase_peligrosidad VARCHAR2(10),
    activo NUMBER(1) DEFAULT 1
);

-- Tabla 19.2: envios_carga
CREATE TABLE envios_carga (
    id_envio NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    codigo_envio VARCHAR2(30) UNIQUE NOT NULL,
    id_vuelo NUMBER NOT NULL,
    id_tipo_carga NUMBER NOT NULL,
    peso_kg NUMBER(10,2) NOT NULL,
    volumen_m3 NUMBER(10,2),
    cantidad_bultos NUMBER,
    contenido VARCHAR2(500) NOT NULL,
    valor_declarado NUMBER(15,2),
    moneda VARCHAR2(3),
    consignador_nombre VARCHAR2(100),
    consignador_documento VARCHAR2(30),
    consignatario_nombre VARCHAR2(100),
    consignatario_documento VARCHAR2(30),
    instrucciones_especiales VARCHAR2(500),
    fecha_recepcion TIMESTAMP DEFAULT SYSTIMESTAMP,
    fecha_embarque DATE,
    estado VARCHAR2(30) DEFAULT 'RECIBIDO' CHECK (estado IN ('RECIBIDO', 'EN_BODEGA', 'CARGADO', 'EN_VUELO', 'DESCARGADO', 'ENTREGADO', 'ADUANA')),
    ubicacion_actual VARCHAR2(100),
    FOREIGN KEY (id_vuelo) REFERENCES vuelos(id_vuelo),
    FOREIGN KEY (id_tipo_carga) REFERENCES tipos_carga(id_tipo_carga)
);

-- Tabla 19.3: manifiestos_carga
CREATE TABLE manifiestos_carga (
    id_manifiesto NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    numero_manifiesto VARCHAR2(30) UNIQUE NOT NULL,
    id_vuelo NUMBER NOT NULL,
    fecha_emision DATE DEFAULT SYSDATE,
    total_bultos NUMBER,
    peso_total_kg NUMBER(10,2),
    volumen_total_m3 NUMBER(10,2),
    valor_total NUMBER(15,2),
    agente_carga VARCHAR2(100),
    documento_adjunto BLOB,
    estado VARCHAR2(20) DEFAULT 'EMITIDO' CHECK (estado IN ('EMITIDO', 'VALIDADO', 'CERRADO')),
    emitido_por NUMBER,
    FOREIGN KEY (id_vuelo) REFERENCES vuelos(id_vuelo),
    FOREIGN KEY (emitido_por) REFERENCES empleados(id_empleado)
);

-- Tabla 19.4: manifiestos_detalle
CREATE TABLE manifiestos_detalle (
    id_detalle NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_manifiesto NUMBER,
    id_envio NUMBER,
    numero_orden NUMBER,
    observaciones VARCHAR2(200),
    FOREIGN KEY (id_manifiesto) REFERENCES manifiestos_carga(id_manifiesto),
    FOREIGN KEY (id_envio) REFERENCES envios_carga(id_envio)
);

-- Tabla 19.5: seguimiento_carga
CREATE TABLE seguimiento_carga (
    id_seguimiento NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_envio NUMBER NOT NULL,
    fecha_hora TIMESTAMP DEFAULT SYSTIMESTAMP,
    ubicacion VARCHAR2(100) NOT NULL,
    estado VARCHAR2(50) NOT NULL,
    responsable VARCHAR2(100),
    observaciones VARCHAR2(500),
    temperatura_registrada NUMBER(5,2),
    incidente NUMBER(1) DEFAULT 0,
    FOREIGN KEY (id_envio) REFERENCES envios_carga(id_envio)
);

-- Tabla 19.6: restricciones_carga
CREATE TABLE restricciones_carga (
    id_restriccion NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_tipo_carga NUMBER,
    id_aerolinea NUMBER,
    permitido NUMBER(1) DEFAULT 1,
    requiere_autorizacion_especial NUMBER(1) DEFAULT 0,
    documento_requerido VARCHAR2(100),
    observaciones VARCHAR2(500),
    FOREIGN KEY (id_tipo_carga) REFERENCES tipos_carga(id_tipo_carga),
    FOREIGN KEY (id_aerolinea) REFERENCES aerolineas(id_aerolinea)
);

-- Tabla 19.7: aduanas_carga
CREATE TABLE aduanas_carga (
    id_registro_aduanal NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_envio NUMBER NOT NULL,
    tipo_operacion VARCHAR2(20) CHECK (tipo_operacion IN ('IMPORTACION', 'EXPORTACION', 'TRANSITO')),
    fecha_revision DATE DEFAULT SYSDATE,
    estado_aduanal VARCHAR2(30) CHECK (estado_aduanal IN ('EN_TRAMITE', 'LIBERADO', 'RETENIDO', 'INCAUTADO')),
    inspector_asignado NUMBER,
    documentos_verificados NUMBER(1) DEFAULT 0,
    impuesto_aplicado NUMBER(15,2),
    moneda_impuesto VARCHAR2(3),
    fecha_liberacion DATE,
    observaciones VARCHAR2(500),
    FOREIGN KEY (id_envio) REFERENCES envios_carga(id_envio),
    FOREIGN KEY (inspector_asignado) REFERENCES empleados(id_empleado)
);

-- Tabla 19.8: inspectores_aduanas
CREATE TABLE inspectores_aduanas (
    id_inspector NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_empleado NUMBER UNIQUE,
    numero_licencia VARCHAR2(30) UNIQUE,
    nivel_autorizacion NUMBER CHECK (nivel_autorizacion BETWEEN 1 AND 5),
    fecha_certificacion DATE,
    fecha_vencimiento_certificacion DATE,
    especialidad VARCHAR2(100),
    activo NUMBER(1) DEFAULT 1,
    FOREIGN KEY (id_empleado) REFERENCES empleados(id_empleado)
);

-- Tabla 19.9: bodegas_carga
CREATE TABLE bodegas_carga (
    id_bodega NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    codigo_bodega VARCHAR2(20) UNIQUE,
    nombre_bodega VARCHAR2(100),
    ubicacion VARCHAR2(200),
    capacidad_m3 NUMBER(10,2),
    capacidad_kg NUMBER(10,2),
    tiene_refrigeracion NUMBER(1) DEFAULT 0,
    temperatura_controlada NUMBER(1) DEFAULT 0,
    tiene_acceso_restringido NUMBER(1) DEFAULT 1,
    activo NUMBER(1) DEFAULT 1
);

-- Tabla 19.10: carga_ubicacion
CREATE TABLE carga_ubicacion (
    id_ubicacion NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_envio NUMBER,
    id_bodega NUMBER,
    fecha_ingreso TIMESTAMP DEFAULT SYSTIMESTAMP,
    fecha_salida TIMESTAMP,
    posicion_estante VARCHAR2(30),
    posicion_fila NUMBER,
    posicion_columna NUMBER,
    responsable_ingreso NUMBER,
    responsable_salida NUMBER,
    FOREIGN KEY (id_envio) REFERENCES envios_carga(id_envio),
    FOREIGN KEY (id_bodega) REFERENCES bodegas_carga(id_bodega),
    FOREIGN KEY (responsable_ingreso) REFERENCES empleados(id_empleado),
    FOREIGN KEY (responsable_salida) REFERENCES empleados(id_empleado)
);

-- =====================================================
-- MÓDULO 20: MANTENIMIENTO PREDICTIVO (10 TABLAS)
-- =====================================================

-- Tabla 20.1: sensores_avion
CREATE TABLE sensores_avion (
    id_sensor NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_modelo_avion NUMBER NOT NULL,
    codigo_sensor VARCHAR2(30) UNIQUE NOT NULL,
    tipo_sensor VARCHAR2(50) CHECK (tipo_sensor IN ('TEMPERATURA', 'PRESION', 'VIBRACION', 'VELOCIDAD', 'ALTITUD', 'COMBUSTIBLE', 'MOTOR', 'HIDRAULICO')),
    ubicacion_fisica VARCHAR2(100),
    fabricante VARCHAR2(50),
    modelo_sensor VARCHAR2(50),
    numero_serie VARCHAR2(50) UNIQUE,
    fecha_instalacion DATE,
    fecha_ultima_calibracion DATE,
    frecuencia_lectura_segundos NUMBER,
    activo NUMBER(1) DEFAULT 1,
    FOREIGN KEY (id_modelo_avion) REFERENCES modelos_aviones(id_modelo)
);

-- Tabla 20.2: lecturas_sensores
CREATE TABLE lecturas_sensores (
    id_lectura NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_sensor NUMBER NOT NULL,
    id_vuelo NUMBER,
    timestamp_lectura TIMESTAMP DEFAULT SYSTIMESTAMP,
    valor_lectura NUMBER(15,4) NOT NULL,
    unidad_medida VARCHAR2(20),
    calidad_lectura NUMBER(3) CHECK (calidad_lectura BETWEEN 0 AND 100),
    procesado NUMBER(1) DEFAULT 0,
    FOREIGN KEY (id_sensor) REFERENCES sensores_avion(id_sensor),
    FOREIGN KEY (id_vuelo) REFERENCES vuelos(id_vuelo)
);

-- Tabla 20.3: alertas_tecnicas
CREATE TABLE alertas_tecnicas (
    id_alerta_tecnica NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_lectura NUMBER,
    nivel_alerta VARCHAR2(20) CHECK (nivel_alerta IN ('INFORMATIVO', 'PREVENTIVO', 'CRITICO', 'EMERGENCIA')),
    tipo_alerta VARCHAR2(50),
    descripcion VARCHAR2(500) NOT NULL,
    valor_umbral NUMBER(15,4),
    valor_actual NUMBER(15,4),
    fecha_alerta TIMESTAMP DEFAULT SYSTIMESTAMP,
    atendida NUMBER(1) DEFAULT 0,
    fecha_atencion TIMESTAMP,
    atendido_por NUMBER,
    acciones_tomadas VARCHAR2(500),
    FOREIGN KEY (id_lectura) REFERENCES lecturas_sensores(id_lectura),
    FOREIGN KEY (atendido_por) REFERENCES empleados(id_empleado)
);

-- Tabla 20.4: piezas_reemplazo
CREATE TABLE piezas_reemplazo (
    id_pieza NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    codigo_pieza VARCHAR2(30) UNIQUE NOT NULL,
    nombre_pieza VARCHAR2(100) NOT NULL,
    descripcion VARCHAR2(500),
    id_modelo_avion NUMBER,
    id_fabricante NUMBER,
    numero_parte_fabricante VARCHAR2(50),
    stock_actual NUMBER DEFAULT 0,
    stock_minimo NUMBER DEFAULT 5,
    stock_maximo NUMBER DEFAULT 50,
    ubicacion_almacen VARCHAR2(100),
    precio_unitario NUMBER(12,2),
    moneda VARCHAR2(3),
    tiempo_reorden_dias NUMBER,
    activo NUMBER(1) DEFAULT 1,
    FOREIGN KEY (id_modelo_avion) REFERENCES modelos_aviones(id_modelo),
    FOREIGN KEY (id_fabricante) REFERENCES fabricantes_aviones(id_fabricante)
);

-- Tabla 20.5: ordenes_mantenimiento_predictivo
CREATE TABLE ordenes_mantenimiento_predictivo (
    id_orden_mp NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_alerta_tecnica NUMBER,
    id_pieza NUMBER,
    id_avion_matricula VARCHAR2(20),
    fecha_creacion TIMESTAMP DEFAULT SYSTIMESTAMP,
    prioridad VARCHAR2(20) CHECK (prioridad IN ('BAJA', 'MEDIA', 'ALTA', 'URGENTE')),
    descripcion_trabajo VARCHAR2(500),
    tecnico_asignado NUMBER,
    fecha_inicio_estimada DATE,
    fecha_fin_estimada DATE,
    fecha_inicio_real DATE,
    fecha_fin_real DATE,
    estado VARCHAR2(30) DEFAULT 'PENDIENTE' CHECK (estado IN ('PENDIENTE', 'ASIGNADO', 'EN_PROCESO', 'COMPLETADO', 'CANCELADO')),
    horas_trabajadas NUMBER,
    costo_estimado NUMBER(12,2),
    costo_real NUMBER(12,2),
    observaciones VARCHAR2(500),
    FOREIGN KEY (id_alerta_tecnica) REFERENCES alertas_tecnicas(id_alerta_tecnica),
    FOREIGN KEY (id_pieza) REFERENCES piezas_reemplazo(id_pieza),
    FOREIGN KEY (tecnico_asignado) REFERENCES empleados(id_empleado)
);

-- Tabla 20.6: checklists_mantenimiento
CREATE TABLE checklists_mantenimiento (
    id_checklist NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_modelo_avion NUMBER,
    codigo_checklist VARCHAR2(30) UNIQUE,
    nombre_checklist VARCHAR2(100),
    tipo_mantenimiento VARCHAR2(30) CHECK (tipo_mantenimiento IN ('PREVENTIVO', 'PREDICTIVO', 'CORRECTIVO', 'MAYOR')),
    frecuencia_horas_vuelo NUMBER,
    frecuencia_dias NUMBER,
    tiempo_estimado_minutos NUMBER,
    requiere_herramientas_especiales NUMBER(1) DEFAULT 0,
    requiere_certificacion NUMBER(1) DEFAULT 0,
    activo NUMBER(1) DEFAULT 1,
    FOREIGN KEY (id_modelo_avion) REFERENCES modelos_aviones(id_modelo)
);

-- Tabla 20.7: checklist_tareas
CREATE TABLE checklist_tareas (
    id_tarea NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_checklist NUMBER,
    numero_orden NUMBER,
    descripcion_tarea VARCHAR2(500) NOT NULL,
    tiempo_estimado_minutos NUMBER,
    requiere_inspeccion NUMBER(1) DEFAULT 0,
    parametros_medicion VARCHAR2(200),
    valores_aceptables VARCHAR2(200),
    FOREIGN KEY (id_checklist) REFERENCES checklists_mantenimiento(id_checklist)
);

-- Tabla 20.8: checklist_ejecucion
CREATE TABLE checklist_ejecucion (
    id_ejecucion NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_orden_mp NUMBER,
    id_checklist NUMBER,
    fecha_inicio TIMESTAMP,
    fecha_fin TIMESTAMP,
    tecnico_ejecutor NUMBER,
    supervisor NUMBER,
    resultado VARCHAR2(20) CHECK (resultado IN ('APROBADO', 'APROBADO_CON_OBS', 'RECHAZADO')),
    observaciones VARCHAR2(500),
    firma_tecnico BLOB,
    firma_supervisor BLOB,
    FOREIGN KEY (id_orden_mp) REFERENCES ordenes_mantenimiento_predictivo(id_orden_mp),
    FOREIGN KEY (id_checklist) REFERENCES checklists_mantenimiento(id_checklist),
    FOREIGN KEY (tecnico_ejecutor) REFERENCES empleados(id_empleado),
    FOREIGN KEY (supervisor) REFERENCES empleados(id_empleado)
);

-- Tabla 20.9: tareas_ejecutadas
CREATE TABLE tareas_ejecutadas (
    id_tarea_ejecutada NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_ejecucion NUMBER,
    id_tarea NUMBER,
    fecha_ejecucion TIMESTAMP,
    tiempo_real_minutos NUMBER,
    resultados_medicion VARCHAR2(500),
    conforme NUMBER(1) DEFAULT 1,
    observaciones_tarea VARCHAR2(500),
    FOREIGN KEY (id_ejecucion) REFERENCES checklist_ejecucion(id_ejecucion),
    FOREIGN KEY (id_tarea) REFERENCES checklist_tareas(id_tarea)
);

-- Tabla 20.10: proveedores_repuestos
CREATE TABLE proveedores_repuestos (
    id_proveedor_repuesto NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_proveedor NUMBER,
    id_pieza NUMBER,
    precio_contrato NUMBER(12,2),
    tiempo_entrega_dias NUMBER,
    calificacion NUMBER(1),
    ultima_compra DATE,
    activo NUMBER(1) DEFAULT 1,
    FOREIGN KEY (id_proveedor) REFERENCES proveedores(id_proveedor),
    FOREIGN KEY (id_pieza) REFERENCES piezas_reemplazo(id_pieza)
);

-- =====================================================
-- GRUPO 3: SEGURIDAD Y CONTROL
-- =====================================================

-- =====================================================
-- MÓDULO 10: SEGURIDAD (8 TABLAS)
-- =====================================================

-- Tabla 10.1: incidentes
CREATE TABLE incidentes (
    id_incidente NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_pasajero NUMBER,
    id_vuelo NUMBER,
    codigo_aeropuerto VARCHAR2(10),
    fecha_incidente DATE DEFAULT SYSDATE,
    hora_incidente TIMESTAMP,
    tipo_incidente VARCHAR2(50) CHECK (tipo_incidente IN ('ARRESTO', 'INFRACCION', 'INCIDENTE', 'EMERGENCIA_MEDICA', 'SEGURIDAD', 'DISCUSION', 'ROBO')),
    nivel_gravedad VARCHAR2(20) CHECK (nivel_gravedad IN ('BAJO', 'MEDIO', 'ALTO', 'CRITICO')),
    descripcion VARCHAR2(500) NOT NULL,
    lugar_incidente VARCHAR2(100),
    autoridad_involucrada VARCHAR2(100),
    oficial_a_cargo VARCHAR2(100),
    resolucion VARCHAR2(500),
    fecha_resolucion DATE,
    estado VARCHAR2(20) DEFAULT 'ACTIVO',
    requiere_seguimiento NUMBER(1) DEFAULT 0,
    FOREIGN KEY (id_pasajero) REFERENCES pasajeros(id_pasajero),
    FOREIGN KEY (id_vuelo) REFERENCES vuelos(id_vuelo),
    FOREIGN KEY (codigo_aeropuerto) REFERENCES aeropuertos(codigo_aeropuerto)
);

-- Tabla 10.2: tipos_incidentes
CREATE TABLE tipos_incidentes (
    id_tipo_incidente NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre_tipo VARCHAR2(50),
    descripcion VARCHAR2(200),
    protocolo_accion VARCHAR2(500),
    tiempo_respuesta_estimado NUMBER,
    activo NUMBER(1) DEFAULT 1
);

-- Tabla 10.3: incidentes_involucrados
CREATE TABLE incidentes_involucrados (
    id_involucrado NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_incidente NUMBER,
    tipo_persona VARCHAR2(30) CHECK (tipo_persona IN ('PASAJERO', 'TRIPULANTE', 'EMPLEADO', 'VISITANTE', 'AUTORIDAD')),
    id_pasajero NUMBER,
    id_tripulante NUMBER,
    nombre_completo VARCHAR2(200),
    tipo_documento VARCHAR2(20),
    numero_documento VARCHAR2(30),
    nacionalidad VARCHAR2(50),
    rol_en_incidente VARCHAR2(100),
    declaracion VARCHAR2(1000),
    FOREIGN KEY (id_incidente) REFERENCES incidentes(id_incidente),
    FOREIGN KEY (id_pasajero) REFERENCES pasajeros(id_pasajero),
    FOREIGN KEY (id_tripulante) REFERENCES tripulacion(id_tripulante)
);

-- Tabla 10.4: incidentes_evidencia
CREATE TABLE incidentes_evidencia (
    id_evidencia NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_incidente NUMBER,
    tipo_evidencia VARCHAR2(50) CHECK (tipo_evidencia IN ('FOTO', 'VIDEO', 'DOCUMENTO', 'TESTIMONIO', 'OBJETO')),
    descripcion VARCHAR2(200),
    archivo_evidencia BLOB,
    fecha_registro TIMESTAMP,
    registrado_por VARCHAR2(100),
    FOREIGN KEY (id_incidente) REFERENCES incidentes(id_incidente)
);

-- Tabla 10.5: incidentes_medidas
CREATE TABLE incidentes_medidas (
    id_medida NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_incidente NUMBER,
    tipo_medida VARCHAR2(50) CHECK (tipo_medida IN ('ADVERTENCIA', 'MULTA', 'ARRESTO', 'EXPULSION', 'PROHIBICION_VUELO', 'OTRA')),
    descripcion VARCHAR2(500),
    fecha_aplicacion TIMESTAMP,
    aplicado_por VARCHAR2(100),
    vigencia_dias NUMBER,
    fecha_vencimiento DATE,
    observaciones VARCHAR2(500),
    FOREIGN KEY (id_incidente) REFERENCES incidentes(id_incidente)
);

-- Tabla 10.6: prohibiciones_vuelo
CREATE TABLE prohibiciones_vuelo (
    id_prohibicion NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_pasajero NUMBER,
    fecha_prohibicion DATE,
    fecha_inicio DATE,
    fecha_fin DATE,
    motivo VARCHAR2(500),
    id_incidente NUMBER,
    autoridad_emite VARCHAR2(100),
    activa NUMBER(1) DEFAULT 1,
    FOREIGN KEY (id_pasajero) REFERENCES pasajeros(id_pasajero),
    FOREIGN KEY (id_incidente) REFERENCES incidentes(id_incidente)
);

-- Tabla 10.7: emergencias_medicas
CREATE TABLE emergencias_medicas (
    id_emergencia NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_pasajero NUMBER,
    id_vuelo NUMBER,
    codigo_aeropuerto VARCHAR2(10),
    fecha_emergencia TIMESTAMP,
    tipo_emergencia VARCHAR2(50),
    sintomas VARCHAR2(500),
    diagnostico_inicial VARCHAR2(500),
    personal_atendio VARCHAR2(100),
    tratamiento VARCHAR2(500),
    requiere_hospitalizacion NUMBER(1) DEFAULT 0,
    hospital_destino VARCHAR2(100),
    fecha_alta DATE,
    FOREIGN KEY (id_pasajero) REFERENCES pasajeros(id_pasajero),
    FOREIGN KEY (id_vuelo) REFERENCES vuelos(id_vuelo),
    FOREIGN KEY (codigo_aeropuerto) REFERENCES aeropuertos(codigo_aeropuerto)
);

-- Tabla 10.8: botiquines_vuelo
CREATE TABLE botiquines_vuelo (
    id_botiquin NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_vuelo NUMBER,
    fecha_verificacion DATE,
    contenido_completo NUMBER(1) DEFAULT 1,
    medicamentos_caducados NUMBER(1) DEFAULT 0,
    observaciones VARCHAR2(500),
    verificado_por VARCHAR2(100),
    FOREIGN KEY (id_vuelo) REFERENCES vuelos(id_vuelo)
);

-- =====================================================
-- MÓDULO 11: SEGURIDAD AEROPORTUARIA (5 TABLAS)
-- =====================================================

-- Tabla 11.1: seguridad_controles
CREATE TABLE seguridad_controles (
    id_control NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    codigo_aeropuerto VARCHAR2(10),
    fecha_control DATE,
    hora_control TIMESTAMP,
    tipo_control VARCHAR2(50) CHECK (tipo_control IN ('RAYOS_X', 'REVISION_MANUAL', 'CANES', 'DOCUMENTOS')),
    numero_pasajeros_revisados NUMBER,
    numero_incidencias NUMBER,
    supervisor VARCHAR2(100),
    observaciones VARCHAR2(500),
    FOREIGN KEY (codigo_aeropuerto) REFERENCES aeropuertos(codigo_aeropuerto)
);

-- Tabla 11.2: objetos_decomisados
CREATE TABLE objetos_decomisados (
    id_decomiso NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_control NUMBER,
    id_pasajero NUMBER,
    tipo_objeto VARCHAR2(50),
    descripcion VARCHAR2(200),
    cantidad NUMBER,
    motivo_decomiso VARCHAR2(200),
    destino_final VARCHAR2(100),
    fecha_registro TIMESTAMP,
    registrado_por VARCHAR2(100),
    FOREIGN KEY (id_control) REFERENCES seguridad_controles(id_control),
    FOREIGN KEY (id_pasajero) REFERENCES pasajeros(id_pasajero)
);

-- Tabla 11.3: visitas_seguridad
CREATE TABLE visitas_seguridad (
    id_visita NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    codigo_aeropuerto VARCHAR2(10),
    fecha_visita DATE,
    hora_entrada TIMESTAMP,
    hora_salida TIMESTAMP,
    nombre_visitante VARCHAR2(100),
    tipo_documento VARCHAR2(20),
    numero_documento VARCHAR2(30),
    empresa VARCHAR2(100),
    motivo_visita VARCHAR2(200),
    persona_autoriza VARCHAR2(100),
    area_visitada VARCHAR2(100),
    escort_requerido NUMBER(1) DEFAULT 0,
    escort_asignado VARCHAR2(100),
    FOREIGN KEY (codigo_aeropuerto) REFERENCES aeropuertos(codigo_aeropuerto)
);

-- Tabla 11.4: alertas_seguridad
CREATE TABLE alertas_seguridad (
    id_alerta NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    codigo_aeropuerto VARCHAR2(10),
    nivel_alerta VARCHAR2(20) CHECK (nivel_alerta IN ('VERDE', 'AMARILLO', 'NARANJA', 'ROJO')),
    fecha_inicio TIMESTAMP,
    fecha_fin TIMESTAMP,
    motivo VARCHAR2(500),
    medidas_adicionales VARCHAR2(1000),
    activa NUMBER(1) DEFAULT 1,
    emitida_por VARCHAR2(100),
    FOREIGN KEY (codigo_aeropuerto) REFERENCES aeropuertos(codigo_aeropuerto)
);

-- Tabla 11.5: accesos_areas_restringidas
CREATE TABLE accesos_areas_restringidas (
    id_acceso NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_empleado NUMBER,
    area_acceso VARCHAR2(100),
    fecha_hora_acceso TIMESTAMP,
    tipo_acceso VARCHAR2(20) CHECK (tipo_acceso IN ('ENTRADA', 'SALIDA')),
    metodo_autenticacion VARCHAR2(30) CHECK (metodo_autenticacion IN ('HUELLA', 'TARJETA', 'CODIGO')),
    autorizado NUMBER(1) DEFAULT 1,
    observaciones VARCHAR2(200),
    FOREIGN KEY (id_empleado) REFERENCES empleados(id_empleado)
);

-- =====================================================
-- MÓDULO 12: OBJETOS PERDIDOS (5 TABLAS)
-- =====================================================

-- Tabla 12.1: objetos_perdidos
CREATE TABLE objetos_perdidos (
    id_objeto NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    descripcion VARCHAR2(200) NOT NULL,
    categoria_objeto VARCHAR2(50),
    fecha_reporte DATE DEFAULT SYSDATE,
    hora_reporte TIMESTAMP,
    lugar_encontrado VARCHAR2(50) CHECK (lugar_encontrado IN ('AEROPUERTO', 'VUELO', 'SALA_ESPERA', 'RESTAURANTE', 'TIENDA', 'ESTACIONAMIENTO', 'BAÑOS')),
    ubicacion_detallada VARCHAR2(200),
    id_vuelo NUMBER,
    codigo_aeropuerto VARCHAR2(10),
    color VARCHAR2(30),
    marca VARCHAR2(50),
    modelo VARCHAR2(50),
    numero_serie VARCHAR2(50),
    valor_estimado NUMBER(10,2),
    encontrado_por VARCHAR2(100),
    ubicacion_actual VARCHAR2(100),
    estado VARCHAR2(20) DEFAULT 'ENCONTRADO' CHECK (estado IN ('ENCONTRADO', 'ENTREGADO', 'ELIMINADO', 'EN_PROCESO')),
    fecha_entrega DATE,
    id_pasajero_entrega NUMBER,
    observaciones VARCHAR2(500),
    foto_objeto BLOB,
    FOREIGN KEY (id_vuelo) REFERENCES vuelos(id_vuelo),
    FOREIGN KEY (codigo_aeropuerto) REFERENCES aeropuertos(codigo_aeropuerto),
    FOREIGN KEY (id_pasajero_entrega) REFERENCES pasajeros(id_pasajero)
);

-- Tabla 12.2: categorias_objetos
CREATE TABLE categorias_objetos (
    id_categoria NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre_categoria VARCHAR2(50),
    descripcion VARCHAR2(200),
    activo NUMBER(1) DEFAULT 1
);

-- Tabla 12.3: objetos_seguimiento
CREATE TABLE objetos_seguimiento (
    id_seguimiento NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_objeto NUMBER,
    fecha_movimiento TIMESTAMP,
    ubicacion VARCHAR2(100),
    responsable VARCHAR2(100),
    accion VARCHAR2(100),
    observaciones VARCHAR2(200),
    FOREIGN KEY (id_objeto) REFERENCES objetos_perdidos(id_objeto)
);

-- Tabla 12.4: objetos_entregados
CREATE TABLE objetos_entregados (
    id_entrega NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_objeto NUMBER,
    id_pasajero NUMBER,
    fecha_entrega TIMESTAMP,
    documento_identificacion VARCHAR2(50),
    firma_digital BLOB,
    entregado_por VARCHAR2(100),
    observaciones VARCHAR2(200),
    FOREIGN KEY (id_objeto) REFERENCES objetos_perdidos(id_objeto),
    FOREIGN KEY (id_pasajero) REFERENCES pasajeros(id_pasajero)
);

-- Tabla 12.5: reclamaciones_objetos
CREATE TABLE reclamaciones_objetos (
    id_reclamacion NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_pasajero NUMBER,
    id_objeto NUMBER,
    fecha_reclamacion TIMESTAMP,
    descripcion_reclamacion VARCHAR2(500),
    estado VARCHAR2(20) DEFAULT 'PENDIENTE' CHECK (estado IN ('PENDIENTE', 'APROBADA', 'RECHAZADA')),
    fecha_resolucion TIMESTAMP,
    resolucion VARCHAR2(500),
    resuelto_por VARCHAR2(100),
    FOREIGN KEY (id_pasajero) REFERENCES pasajeros(id_pasajero),
    FOREIGN KEY (id_objeto) REFERENCES objetos_perdidos(id_objeto)
);

-- =====================================================
-- GRUPO 4: COMERCIAL Y SERVICIOS
-- =====================================================

-- =====================================================
-- MÓDULO 13: ÁREA COMERCIAL (10 TABLAS)
-- =====================================================

-- Tabla 13.1: concesiones_comerciales
CREATE TABLE concesiones_comerciales (
    id_concesion NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    codigo_aeropuerto VARCHAR2(10),
    nombre_comercial VARCHAR2(100),
    tipo_negocio VARCHAR2(50) CHECK (tipo_negocio IN ('RESTAURANTE', 'TIENDA', 'ALQUILER', 'SERVICIO', 'DUTY_FREE')),
    empresa VARCHAR2(100),
    ruc VARCHAR2(20),
    representante VARCHAR2(100),
    telefono_contacto VARCHAR2(20),
    email_contacto VARCHAR2(100),
    fecha_inicio_concesion DATE,
    fecha_fin_concesion DATE,
    canon_mensual NUMBER(10,2),
    ubicacion_terminal VARCHAR2(50),
    local_numero VARCHAR2(20),
    area_m2 NUMBER,
    activo NUMBER(1) DEFAULT 1,
    FOREIGN KEY (codigo_aeropuerto) REFERENCES aeropuertos(codigo_aeropuerto)
);

-- Tabla 13.2: tiendas_productos
CREATE TABLE tiendas_productos (
    id_producto NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_concesion NUMBER,
    codigo_producto VARCHAR2(30),
    nombre_producto VARCHAR2(100),
    descripcion VARCHAR2(500),
    categoria VARCHAR2(50),
    precio NUMBER(10,2),
    moneda VARCHAR2(3),
    stock_actual NUMBER,
    stock_minimo NUMBER,
    iva_aplicable NUMBER(5,2),
    activo NUMBER(1) DEFAULT 1,
    FOREIGN KEY (id_concesion) REFERENCES concesiones_comerciales(id_concesion)
);

-- Tabla 13.3: tiendas_ventas
CREATE TABLE tiendas_ventas (
    id_venta NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_concesion NUMBER,
    fecha_venta TIMESTAMP,
    id_reserva NUMBER,
    id_pasajero NUMBER,
    tipo_cliente VARCHAR2(20) CHECK (tipo_cliente IN ('PASAJERO', 'VISITANTE', 'TRIPULANTE')),
    subtotal NUMBER(10,2),
    impuestos NUMBER(10,2),
    total NUMBER(10,2),
    metodo_pago VARCHAR2(30),
    tarjeta_numero VARCHAR2(4),
    autorizado_por VARCHAR2(100),
    FOREIGN KEY (id_concesion) REFERENCES concesiones_comerciales(id_concesion),
    FOREIGN KEY (id_reserva) REFERENCES reservas(id_reserva),
    FOREIGN KEY (id_pasajero) REFERENCES pasajeros(id_pasajero)
);

-- Tabla 13.4: ventas_detalle
CREATE TABLE ventas_detalle (
    id_detalle NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_venta NUMBER,
    id_producto NUMBER,
    cantidad NUMBER,
    precio_unitario NUMBER(10,2),
    descuento_aplicado NUMBER(10,2),
    subtotal_linea NUMBER(10,2),
    FOREIGN KEY (id_venta) REFERENCES tiendas_ventas(id_venta),
    FOREIGN KEY (id_producto) REFERENCES tiendas_productos(id_producto)
);

-- Tabla 13.5: restaurantes_menus
CREATE TABLE restaurantes_menus (
    id_menu NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_concesion NUMBER,
    nombre_plato VARCHAR2(100),
    descripcion VARCHAR2(200),
    categoria_menu VARCHAR2(50) CHECK (categoria_menu IN ('DESAYUNO', 'ALMUERZO', 'CENA', 'BEBIDAS', 'POSTRES', 'COMIDA_RAPIDA')),
    precio NUMBER(10,2),
    moneda VARCHAR2(3),
    disponible NUMBER(1) DEFAULT 1,
    tiempo_preparacion_minutos NUMBER,
    calorias NUMBER,
    restricciones_alimenticias VARCHAR2(200),
    FOREIGN KEY (id_concesion) REFERENCES concesiones_comerciales(id_concesion)
);

-- Tabla 13.6: salones_vip
CREATE TABLE salones_vip (
    id_salon NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    codigo_aeropuerto VARCHAR2(10),
    nombre_salon VARCHAR2(100),
    ubicacion VARCHAR2(100),
    capacidad NUMBER,
    horario_apertura VARCHAR2(10),
    horario_cierre VARCHAR2(10),
    servicios VARCHAR2(500),
    requisitos_acceso VARCHAR2(500),
    activo NUMBER(1) DEFAULT 1,
    FOREIGN KEY (codigo_aeropuerto) REFERENCES aeropuertos(codigo_aeropuerto)
);

-- Tabla 13.7: salones_accesos
CREATE TABLE salones_accesos (
    id_acceso NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_salon NUMBER,
    id_pasajero NUMBER,
    id_vuelo NUMBER,
    fecha_acceso DATE,
    hora_entrada TIMESTAMP,
    hora_salida TIMESTAMP,
    tipo_acceso VARCHAR2(30) CHECK (tipo_acceso IN ('PRIMERA_CLASE', 'CLUB', 'PAGO', 'INVITACION')),
    costo NUMBER(10,2),
    autorizado_por VARCHAR2(100),
    FOREIGN KEY (id_salon) REFERENCES salones_vip(id_salon),
    FOREIGN KEY (id_pasajero) REFERENCES pasajeros(id_pasajero),
    FOREIGN KEY (id_vuelo) REFERENCES vuelos(id_vuelo)
);

-- Tabla 13.8: estacionamiento
CREATE TABLE estacionamiento (
    id_estacionamiento NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    codigo_aeropuerto VARCHAR2(10),
    numero_espacio VARCHAR2(20),
    tipo_espacio VARCHAR2(30) CHECK (tipo_espacio IN ('AUTOMOVIL', 'MOTOCICLETA', 'DISCAPACITADO', 'ELECTRICO', 'CARGA')),
    terminal_cercana VARCHAR2(10),
    tarifa_por_hora NUMBER(10,2),
    tarifa_diaria NUMBER(10,2),
    disponible NUMBER(1) DEFAULT 1,
    observaciones VARCHAR2(200),
    FOREIGN KEY (codigo_aeropuerto) REFERENCES aeropuertos(codigo_aeropuerto)
);

-- Tabla 13.9: estacionamiento_registro
CREATE TABLE estacionamiento_registro (
    id_registro NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_espacio NUMBER,
    id_pasajero NUMBER,
    id_vuelo NUMBER,
    placa_vehiculo VARCHAR2(20),
    fecha_entrada TIMESTAMP,
    fecha_salida TIMESTAMP,
    tiempo_total_horas NUMBER,
    tarifa_aplicada NUMBER(10,2),
    total_pagar NUMBER(10,2),
    estado_pago NUMBER(1) DEFAULT 0,
    metodo_pago VARCHAR2(30),
    FOREIGN KEY (id_espacio) REFERENCES estacionamiento(id_estacionamiento),
    FOREIGN KEY (id_pasajero) REFERENCES pasajeros(id_pasajero),
    FOREIGN KEY (id_vuelo) REFERENCES vuelos(id_vuelo)
);

-- Tabla 13.10: publicidad
CREATE TABLE publicidad (
    id_publicidad NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    codigo_aeropuerto VARCHAR2(10),
    ubicacion VARCHAR2(200),
    tipo_publicidad VARCHAR2(30) CHECK (tipo_publicidad IN ('VALLA', 'PANTALLA_DIGITAL', 'BANNER')),
    empresa_anunciante VARCHAR2(100),
    fecha_inicio DATE,
    fecha_fin DATE,
    costo NUMBER(10,2),
    contrato BLOB,
    activo NUMBER(1) DEFAULT 1,
    FOREIGN KEY (codigo_aeropuerto) REFERENCES aeropuertos(codigo_aeropuerto)
);

-- =====================================================
-- MÓDULO 14: SERVICIOS AL PASAJERO (7 TABLAS)
-- =====================================================

-- Tabla 14.1: transporte_terrestre
CREATE TABLE transporte_terrestre (
    id_transporte NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    codigo_aeropuerto VARCHAR2(10),
    tipo_transporte VARCHAR2(30) CHECK (tipo_transporte IN ('TAXI', 'BUS', 'SHUTTLE', 'RENTA_AUTO', 'METRO')),
    empresa VARCHAR2(100),
    telefono_contacto VARCHAR2(20),
    tarifa_estimada VARCHAR2(100),
    horario_operacion VARCHAR2(100),
    activo NUMBER(1) DEFAULT 1,
    FOREIGN KEY (codigo_aeropuerto) REFERENCES aeropuertos(codigo_aeropuerto)
);

-- Tabla 14.2: hoteles_cercanos
CREATE TABLE hoteles_cercanos (
    id_hotel NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    codigo_aeropuerto VARCHAR2(10),
    nombre_hotel VARCHAR2(100),
    categoria VARCHAR2(10) CHECK (categoria IN ('1*', '2*', '3*', '4*', '5*')),
    direccion VARCHAR2(200),
    distancia_km NUMBER,
    telefono VARCHAR2(20),
    email VARCHAR2(100),
    website VARCHAR2(100),
    tarifa_noche_desde NUMBER(10,2),
    tiene_shuttle NUMBER(1) DEFAULT 0,
    activo NUMBER(1) DEFAULT 1,
    FOREIGN KEY (codigo_aeropuerto) REFERENCES aeropuertos(codigo_aeropuerto)
);

-- Tabla 14.3: servicios_aeropuerto
CREATE TABLE servicios_aeropuerto (
    id_servicio NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    codigo_aeropuerto VARCHAR2(10),
    nombre_servicio VARCHAR2(100),
    tipo_servicio VARCHAR2(50) CHECK (tipo_servicio IN ('BANCO', 'CAJERO', 'FARMACIA', 'PRIMEROS_AUXILIOS', 'INFORMACION', 'WIFI', 'BOLETERIA', 'ADUANA', 'MIGRACION')),
    ubicacion VARCHAR2(200),
    horario_apertura VARCHAR2(10),
    horario_cierre VARCHAR2(10),
    telefono_contacto VARCHAR2(20),
    disponible_24h NUMBER(1) DEFAULT 0,
    activo NUMBER(1) DEFAULT 1,
    FOREIGN KEY (codigo_aeropuerto) REFERENCES aeropuertos(codigo_aeropuerto)
);

-- Tabla 14.4: quejas_sugerencias
CREATE TABLE quejas_sugerencias (
    id_queja NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_pasajero NUMBER,
    id_vuelo NUMBER,
    tipo_contacto VARCHAR2(20) CHECK (tipo_contacto IN ('QUEJA', 'SUGERENCIA', 'FELICITACION', 'RECLAMO')),
    fecha_contacto TIMESTAMP,
    medio_recepcion VARCHAR2(30) CHECK (medio_recepcion IN ('WEB', 'APP', 'PRESENCIAL', 'TELEFONICO', 'EMAIL')),
    descripcion VARCHAR2(1000),
    area_relacionada VARCHAR2(50),
    estado VARCHAR2(20) DEFAULT 'RECIBIDO',
    fecha_respuesta TIMESTAMP,
    respuesta VARCHAR2(1000),
    satisfaccion_respuesta NUMBER(1),
    FOREIGN KEY (id_pasajero) REFERENCES pasajeros(id_pasajero),
    FOREIGN KEY (id_vuelo) REFERENCES vuelos(id_vuelo)
);

-- Tabla 14.5: encuestas_satisfaccion
CREATE TABLE encuestas_satisfaccion (
    id_encuesta NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_pasajero NUMBER,
    id_vuelo NUMBER,
    fecha_encuesta TIMESTAMP,
    puntuacion_general NUMBER(1) CHECK (puntuacion_general BETWEEN 1 AND 5),
    puntuacion_checkin NUMBER(1) CHECK (puntuacion_checkin BETWEEN 1 AND 5),
    puntuacion_abordaje NUMBER(1) CHECK (puntuacion_abordaje BETWEEN 1 AND 5),
    puntuacion_comodidad NUMBER(1) CHECK (puntuacion_comodidad BETWEEN 1 AND 5),
    puntuacion_limpieza NUMBER(1) CHECK (puntuacion_limpieza BETWEEN 1 AND 5),
    puntuacion_atencion NUMBER(1) CHECK (puntuacion_atencion BETWEEN 1 AND 5),
    puntuacion_equipaje NUMBER(1) CHECK (puntuacion_equipaje BETWEEN 1 AND 5),
    comentarios VARCHAR2(1000),
    recomienda NUMBER(1) DEFAULT 1,
    FOREIGN KEY (id_pasajero) REFERENCES pasajeros(id_pasajero),
    FOREIGN KEY (id_vuelo) REFERENCES vuelos(id_vuelo)
);

-- Tabla 14.6: programa_lealtad
CREATE TABLE programa_lealtad (
    id_lealtad NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_pasajero NUMBER,
    nivel_membresia VARCHAR2(20) CHECK (nivel_membresia IN ('BRONCE', 'PLATA', 'ORO', 'PLATINO')),
    puntos_acumulados NUMBER DEFAULT 0,
    puntos_canjeables NUMBER DEFAULT 0,
    fecha_ingreso DATE,
    fecha_ultima_actividad DATE,
    millas_acumuladas NUMBER DEFAULT 0,
    beneficios_activos VARCHAR2(500),
    tarjeta_numero VARCHAR2(30),
    activo NUMBER(1) DEFAULT 1,
    FOREIGN KEY (id_pasajero) REFERENCES pasajeros(id_pasajero)
);

-- Tabla 14.7: atencion_especial
CREATE TABLE atencion_especial (
    id_atencion NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_pasajero NUMBER,
    id_reserva NUMBER,
    tipo_atencion VARCHAR2(50) CHECK (tipo_atencion IN ('SILLA_RUEDAS', 'ASISTENCIA_VISUAL', 'ASISTENCIA_AUDITIVA')),
    fecha_solicitud TIMESTAMP,
    fecha_atencion TIMESTAMP,
    asistente_asignado VARCHAR2(100),
    observaciones VARCHAR2(500),
    FOREIGN KEY (id_pasajero) REFERENCES pasajeros(id_pasajero),
    FOREIGN KEY (id_reserva) REFERENCES reservas(id_reserva)
);

-- =====================================================
-- MÓDULO 27: TRANSPORTE TERRESTRE AMPLIADO (10 TABLAS)
-- =====================================================

-- Tabla 27.1: rutas_transporte_terrestre
CREATE TABLE rutas_transporte_terrestre (
    id_ruta_transporte NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    codigo_ruta VARCHAR2(20) UNIQUE NOT NULL,
    nombre_ruta VARCHAR2(100) NOT NULL,
    origen VARCHAR2(100) NOT NULL,
    destino VARCHAR2(100) NOT NULL,
    distancia_km NUMBER(8,2),
    duracion_estimada_minutos NUMBER,
    tipo_ruta VARCHAR2(30) CHECK (tipo_ruta IN ('URBANA', 'INTERURBANA', 'AEROPUERTO_HOTEL', 'AEROPUERTO_CENTRO')),
    frecuencia_servicio VARCHAR2(50),
    activa NUMBER(1) DEFAULT 1
);

-- Tabla 27.2: vehiculos_transporte
CREATE TABLE vehiculos_transporte (
    id_vehiculo_transporte NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    placa VARCHAR2(20) UNIQUE NOT NULL,
    tipo_vehiculo VARCHAR2(30) CHECK (tipo_vehiculo IN ('BUS', 'MICROBUS', 'TAXI', 'VAN', 'AUTO', 'MOTOCICLETA')),
    marca VARCHAR2(50),
    modelo VARCHAR2(50),
    anio NUMBER,
    capacidad_pasajeros NUMBER,
    capacidad_maletas NUMBER,
    tiene_aire_acondicionado NUMBER(1) DEFAULT 1,
    tiene_wifi NUMBER(1) DEFAULT 0,
    tiene_accesibilidad NUMBER(1) DEFAULT 0,
    propietario VARCHAR2(100),
    empresa_operadora VARCHAR2(100),
    fecha_ultimo_mantenimiento DATE,
    fecha_proximo_mantenimiento DATE,
    disponible NUMBER(1) DEFAULT 1,
    activo NUMBER(1) DEFAULT 1
);

-- Tabla 27.3: choferes_transporte
CREATE TABLE choferes_transporte (
    id_chofer_transporte NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombres VARCHAR2(100) NOT NULL,
    apellidos VARCHAR2(100) NOT NULL,
    tipo_documento VARCHAR2(20),
    numero_documento VARCHAR2(30) UNIQUE,
    licencia_conducir VARCHAR2(30) UNIQUE NOT NULL,
    categoria_licencia VARCHAR2(10),
    fecha_vencimiento_licencia DATE NOT NULL,
    telefono VARCHAR2(20),
    email VARCHAR2(100),
    fecha_contratacion DATE,
    empresa_contratante VARCHAR2(100),
    certificaciones VARCHAR2(500),
    idiomas VARCHAR2(200),
    disponible NUMBER(1) DEFAULT 1,
    activo NUMBER(1) DEFAULT 1
);

-- Tabla 27.4: asignacion_vehiculos_rutas
CREATE TABLE asignacion_vehiculos_rutas (
    id_asignacion_vehiculo_ruta NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_vehiculo_transporte NUMBER NOT NULL,
    id_ruta_transporte NUMBER NOT NULL,
    fecha_asignacion DATE DEFAULT SYSDATE,
    fecha_inicio_vigencia DATE NOT NULL,
    fecha_fin_vigencia DATE,
    horario_servicio VARCHAR2(500),
    activa NUMBER(1) DEFAULT 1,
    FOREIGN KEY (id_vehiculo_transporte) REFERENCES vehiculos_transporte(id_vehiculo_transporte),
    FOREIGN KEY (id_ruta_transporte) REFERENCES rutas_transporte_terrestre(id_ruta_transporte)
);

-- Tabla 27.5: reservas_transporte_terrestre
CREATE TABLE reservas_transporte_terrestre (
    id_reserva_transporte NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    codigo_reserva_transporte VARCHAR2(30) UNIQUE NOT NULL,
    id_pasajero NUMBER NOT NULL,
    id_ruta_transporte NUMBER NOT NULL,
    tipo_servicio VARCHAR2(30) CHECK (tipo_servicio IN ('COMPARTIDO', 'PRIVADO', 'GRUPAL')),
    fecha_reserva TIMESTAMP DEFAULT SYSTIMESTAMP,
    fecha_servicio DATE NOT NULL,
    hora_recogida TIMESTAMP NOT NULL,
    lugar_recogida VARCHAR2(200) NOT NULL,
    lugar_destino VARCHAR2(200) NOT NULL,
    numero_pasajeros NUMBER DEFAULT 1,
    cantidad_maletas NUMBER,
    id_vuelo_asociado NUMBER,
    instrucciones_especiales VARCHAR2(500),
    estado_reserva VARCHAR2(30) DEFAULT 'CONFIRMADA' CHECK (estado_reserva IN ('CONFIRMADA', 'ASIGNADA', 'COMPLETADA', 'CANCELADA', 'NO_SHOW')),
    precio_total NUMBER(10,2),
    moneda VARCHAR2(3),
    pagado NUMBER(1) DEFAULT 0,
    FOREIGN KEY (id_pasajero) REFERENCES pasajeros(id_pasajero),
    FOREIGN KEY (id_ruta_transporte) REFERENCES rutas_transporte_terrestre(id_ruta_transporte),
    FOREIGN KEY (id_vuelo_asociado) REFERENCES vuelos(id_vuelo)
);

-- Tabla 27.6: asignacion_servicios_transporte
CREATE TABLE asignacion_servicios_transporte (
    id_asignacion_servicio NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_reserva_transporte NUMBER NOT NULL,
    id_vehiculo_transporte NUMBER,
    id_chofer_transporte NUMBER,
    fecha_asignacion TIMESTAMP DEFAULT SYSTIMESTAMP,
    asignado_por NUMBER,
    hora_llegada_vehiculo TIMESTAMP,
    hora_inicio_servicio TIMESTAMP,
    hora_fin_servicio TIMESTAMP,
    kilometraje_inicio NUMBER,
    kilometraje_fin NUMBER,
    incidencias VARCHAR2(500),
    calificacion_pasajero NUMBER(1),
    comentarios_pasajero VARCHAR2(500),
    UNIQUE(id_reserva_transporte),
    FOREIGN KEY (id_reserva_transporte) REFERENCES reservas_transporte_terrestre(id_reserva_transporte),
    FOREIGN KEY (id_vehiculo_transporte) REFERENCES vehiculos_transporte(id_vehiculo_transporte),
    FOREIGN KEY (id_chofer_transporte) REFERENCES choferes_transporte(id_chofer_transporte),
    FOREIGN KEY (asignado_por) REFERENCES empleados(id_empleado)
);

-- Tabla 27.7: tarifas_transporte_terrestre
CREATE TABLE tarifas_transporte_terrestre (
    id_tarifa_transporte NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_ruta_transporte NUMBER NOT NULL,
    tipo_tarifa VARCHAR2(30) CHECK (tipo_tarifa IN ('NORMAL', 'NOCTURNA', 'FESTIVO', 'ESPECIAL')),
    precio_por_persona NUMBER(10,2),
    precio_vehiculo_privado NUMBER(10,2),
    precio_maleta_extra NUMBER(5,2),
    moneda VARCHAR2(3),
    hora_inicio_aplicacion VARCHAR2(5),
    hora_fin_aplicacion VARCHAR2(5),
    dias_aplicacion VARCHAR2(50),
    fecha_inicio_vigencia DATE NOT NULL,
    fecha_fin_vigencia DATE,
    activa NUMBER(1) DEFAULT 1,
    FOREIGN KEY (id_ruta_transporte) REFERENCES rutas_transporte_terrestre(id_ruta_transporte)
);

-- Tabla 27.8: empresas_transporte
CREATE TABLE empresas_transporte (
    id_empresa_transporte NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre_empresa VARCHAR2(100) NOT NULL,
    nit VARCHAR2(20),
    tipo_empresa VARCHAR2(30) CHECK (tipo_empresa IN ('TAXI', 'BUS', 'RENTA_CAR', 'SHUTTLE', 'TRANSFER')),
    telefono_contacto VARCHAR2(20),
    email_contacto VARCHAR2(100),
    website VARCHAR2(100),
    persona_contacto VARCHAR2(100),
    telefono_emergencia VARCHAR2(20),
    horario_atencion VARCHAR2(100),
    calificacion_promedio NUMBER(2,1),
    autorizada_aeropuerto NUMBER(1) DEFAULT 1,
    fecha_autorizacion DATE,
    fecha_vencimiento_autorizacion DATE,
    activa NUMBER(1) DEFAULT 1
);

-- Tabla 27.9: convenios_hoteles_transporte
CREATE TABLE convenios_hoteles_transporte (
    id_convenio_hotel NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_hotel_cercano NUMBER NOT NULL,
    id_empresa_transporte NUMBER NOT NULL,
    tipo_convenio VARCHAR2(30) CHECK (tipo_convenio IN ('SHUTTLE_GRATUITO', 'TARIFA_PREFERENCIAL', 'EXCLUSIVO')),
    tarifa_especial NUMBER(10,2),
    condiciones VARCHAR2(500),
    fecha_inicio DATE NOT NULL,
    fecha_fin DATE,
    activo NUMBER(1) DEFAULT 1,
    FOREIGN KEY (id_hotel_cercano) REFERENCES hoteles_cercanos(id_hotel),
    FOREIGN KEY (id_empresa_transporte) REFERENCES empresas_transporte(id_empresa_transporte)
);

-- Tabla 27.10: quejas_transporte_terrestre
CREATE TABLE quejas_transporte_terrestre (
    id_queja_transporte NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_reserva_transporte NUMBER NOT NULL,
    id_pasajero NUMBER NOT NULL,
    fecha_queja TIMESTAMP DEFAULT SYSTIMESTAMP,
    tipo_queja VARCHAR2(30) CHECK (tipo_queja IN ('RETRASO', 'CONDUCTOR', 'VEHICULO', 'TARIFA', 'SEGURIDAD', 'ATENCION')),
    descripcion_queja VARCHAR2(1000) NOT NULL,
    evidencia BLOB,
    estado VARCHAR2(30) DEFAULT 'RECIBIDA' CHECK (estado IN ('RECIBIDA', 'EN_INVESTIGACION', 'RESUELTA', 'RECHAZADA')),
    fecha_resolucion TIMESTAMP,
    resolucion VARCHAR2(1000),
    compensacion_ofrecida VARCHAR2(500),
    resuelto_por NUMBER,
    satisfaccion_pasajero NUMBER(1),
    FOREIGN KEY (id_reserva_transporte) REFERENCES reservas_transporte_terrestre(id_reserva_transporte),
    FOREIGN KEY (id_pasajero) REFERENCES pasajeros(id_pasajero),
    FOREIGN KEY (resuelto_por) REFERENCES empleados(id_empleado)
);

-- =====================================================
-- GRUPO 5: FINANZAS Y ADMINISTRACIÓN
-- =====================================================

-- =====================================================
-- MÓDULO 16: FINANZAS Y CONTABILIDAD (10 TABLAS)
-- =====================================================

-- Tabla 16.1: presupuestos
CREATE TABLE presupuestos (
    id_presupuesto NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    anio_fiscal NUMBER,
    mes NUMBER,
    concepto VARCHAR2(200),
    id_departamento NUMBER,
    monto_asignado NUMBER(12,2),
    monto_ejecutado NUMBER(12,2),
    tipo_gasto VARCHAR2(50) CHECK (tipo_gasto IN ('OPERATIVO', 'INVERSION', 'MANTENIMIENTO', 'PERSONAL')),
    observaciones VARCHAR2(500),
    fecha_actualizacion DATE,
    FOREIGN KEY (id_departamento) REFERENCES departamentos(id_departamento)
);

-- Tabla 16.2: ingresos
CREATE TABLE ingresos (
    id_ingreso NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    fecha DATE,
    concepto VARCHAR2(200),
    tipo_ingreso VARCHAR2(50) CHECK (tipo_ingreso IN ('TASA_EMBARQUE', 'CONCESIONES', 'ESTACIONAMIENTO', 'PUBLICIDAD', 'OTROS')),
    id_concesion NUMBER,
    id_vuelo NUMBER,
    monto NUMBER(12,2),
    moneda VARCHAR2(3),
    metodo_pago VARCHAR2(30),
    comprobante VARCHAR2(50),
    registrado_por NUMBER,
    FOREIGN KEY (id_concesion) REFERENCES concesiones_comerciales(id_concesion),
    FOREIGN KEY (id_vuelo) REFERENCES vuelos(id_vuelo),
    FOREIGN KEY (registrado_por) REFERENCES empleados(id_empleado)
);

-- Tabla 16.3: gastos
CREATE TABLE gastos (
    id_gasto NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    fecha DATE,
    concepto VARCHAR2(200),
    tipo_gasto VARCHAR2(50) CHECK (tipo_gasto IN ('SERVICIOS', 'MANTENIMIENTO', 'PERSONAL', 'SUMINISTROS', 'SEGURIDAD', 'OTROS')),
    id_departamento NUMBER,
    proveedor VARCHAR2(100),
    monto NUMBER(12,2),
    moneda VARCHAR2(3),
    factura VARCHAR2(50),
    autorizado_por NUMBER,
    FOREIGN KEY (id_departamento) REFERENCES departamentos(id_departamento),
    FOREIGN KEY (autorizado_por) REFERENCES empleados(id_empleado)
);

-- Tabla 16.4: proveedores
CREATE TABLE proveedores (
    id_proveedor NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre_proveedor VARCHAR2(100),
    tipo_proveedor VARCHAR2(50) CHECK (tipo_proveedor IN ('COMBUSTIBLE', 'CATERING', 'MANTENIMIENTO', 'LIMPIEZA', 'SEGURIDAD', 'TECNOLOGIA')),
    nit VARCHAR2(20),
    direccion VARCHAR2(200),
    telefono VARCHAR2(20),
    email VARCHAR2(100),
    contacto_nombre VARCHAR2(100),
    contacto_telefono VARCHAR2(20),
    condiciones_pago VARCHAR2(100),
    calificacion NUMBER(1),
    activo NUMBER(1) DEFAULT 1
);

-- Tabla 16.5: ordenes_compra
CREATE TABLE ordenes_compra (
    id_orden NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_proveedor NUMBER,
    fecha_orden DATE,
    fecha_entrega_estimada DATE,
    fecha_entrega_real DATE,
    estado VARCHAR2(20) DEFAULT 'PENDIENTE',
    subtotal NUMBER(12,2),
    impuestos NUMBER(12,2),
    total NUMBER(12,2),
    condiciones_entrega VARCHAR2(500),
    solicitado_por NUMBER,
    autorizado_por NUMBER,
    FOREIGN KEY (id_proveedor) REFERENCES proveedores(id_proveedor),
    FOREIGN KEY (solicitado_por) REFERENCES empleados(id_empleado),
    FOREIGN KEY (autorizado_por) REFERENCES empleados(id_empleado)
);

-- Tabla 16.6: ordenes_detalle
CREATE TABLE ordenes_detalle (
    id_detalle NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_orden NUMBER,
    descripcion VARCHAR2(200),
    cantidad NUMBER,
    precio_unitario NUMBER(10,2),
    subtotal_linea NUMBER(10,2),
    observaciones VARCHAR2(200),
    FOREIGN KEY (id_orden) REFERENCES ordenes_compra(id_orden)
);

-- Tabla 16.7: tasas_aeroportuarias
CREATE TABLE tasas_aeroportuarias (
    id_tasa NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre_tasa VARCHAR2(100),
    tipo_tasa VARCHAR2(30) CHECK (tipo_tasa IN ('INTERNACIONAL', 'NACIONAL', 'SEGURIDAD', 'COMBUSTIBLE', 'ESTACIONAMIENTO')),
    monto NUMBER(10,2),
    moneda VARCHAR2(3),
    calculo_porcentaje NUMBER(5,2),
    aplica_a VARCHAR2(50) CHECK (aplica_a IN ('PASAJERO', 'AEROLINEA', 'CARGA', 'AVION')),
    activa NUMBER(1) DEFAULT 1,
    fecha_actualizacion DATE
);

-- Tabla 16.8: tasas_aplicadas
CREATE TABLE tasas_aplicadas (
    id_aplicacion NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_tasa NUMBER,
    id_vuelo NUMBER,
    id_reserva NUMBER,
    fecha_aplicacion DATE,
    monto_aplicado NUMBER(10,2),
    facturado NUMBER(1) DEFAULT 0,
    fecha_factura DATE,
    FOREIGN KEY (id_tasa) REFERENCES tasas_aeroportuarias(id_tasa),
    FOREIGN KEY (id_vuelo) REFERENCES vuelos(id_vuelo),
    FOREIGN KEY (id_reserva) REFERENCES reservas(id_reserva)
);

-- Tabla 16.9: cuentas_bancarias
CREATE TABLE cuentas_bancarias (
    id_cuenta NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    banco VARCHAR2(100),
    tipo_cuenta VARCHAR2(30) CHECK (tipo_cuenta IN ('MONETARIA', 'AHORRO', 'INVERSION')),
    numero_cuenta VARCHAR2(30) UNIQUE,
    moneda VARCHAR2(3),
    saldo_actual NUMBER(15,2),
    fecha_apertura DATE,
    estado VARCHAR2(20) DEFAULT 'ACTIVA',
    responsable VARCHAR2(100)
);

-- Tabla 16.10: movimientos_bancarios
CREATE TABLE movimientos_bancarios (
    id_movimiento NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_cuenta NUMBER,
    fecha DATE,
    tipo_movimiento VARCHAR2(30) CHECK (tipo_movimiento IN ('DEPOSITO', 'RETIRO', 'TRANSFERENCIA', 'PAGO', 'COBRO')),
    concepto VARCHAR2(200),
    monto NUMBER(12,2),
    saldo_resultante NUMBER(12,2),
    referencia VARCHAR2(50),
    conciliado NUMBER(1) DEFAULT 0,
    FOREIGN KEY (id_cuenta) REFERENCES cuentas_bancarias(id_cuenta)
);

-- =====================================================
-- MÓDULO 22: GESTIÓN DE COMBUSTIBLE (10 TABLAS)
-- =====================================================

-- Tabla 22.1: tanques_combustible
CREATE TABLE tanques_combustible (
    id_tanque NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    codigo_tanque VARCHAR2(20) UNIQUE NOT NULL,
    nombre_tanque VARCHAR2(100),
    tipo_combustible VARCHAR2(20) CHECK (tipo_combustible IN ('JET_A', 'JET_A1', 'JET_B', 'AVGAS')),
    capacidad_litros NUMBER(15,2) NOT NULL,
    nivel_actual_litros NUMBER(15,2),
    porcentaje_llenado NUMBER(5,2),
    ubicacion VARCHAR2(100),
    fecha_ultima_inspeccion DATE,
    fecha_ultima_calibracion DATE,
    activo NUMBER(1) DEFAULT 1
);

-- Tabla 22.2: proveedores_combustible
CREATE TABLE proveedores_combustible (
    id_proveedor_combustible NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_proveedor NUMBER UNIQUE,
    tipo_combustible_suministrado VARCHAR2(20),
    precio_compra_galon NUMBER(10,4),
    moneda VARCHAR2(3),
    contrato_vigente NUMBER(1) DEFAULT 1,
    fecha_inicio_contrato DATE,
    fecha_fin_contrato DATE,
    volumen_minimo_contrato NUMBER(15,2),
    condiciones_especiales VARCHAR2(500),
    FOREIGN KEY (id_proveedor) REFERENCES proveedores(id_proveedor)
);

-- Tabla 22.3: pedidos_combustible
CREATE TABLE pedidos_combustible (
    id_pedido_combustible NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    numero_pedido VARCHAR2(30) UNIQUE NOT NULL,
    id_vuelo NUMBER NOT NULL,
    cantidad_solicitada_litros NUMBER(15,2) NOT NULL,
    tipo_combustible VARCHAR2(20),
    fecha_pedido TIMESTAMP DEFAULT SYSTIMESTAMP,
    fecha_requerida TIMESTAMP,
    estado_pedido VARCHAR2(30) DEFAULT 'SOLICITADO' CHECK (estado_pedido IN ('SOLICITADO', 'APROBADO', 'EN_PROCESO', 'COMPLETADO', 'CANCELADO')),
    prioridad VARCHAR2(20) CHECK (prioridad IN ('NORMAL', 'ALTA', 'EMERGENCIA')),
    solicitado_por NUMBER,
    aprobado_por NUMBER,
    observaciones VARCHAR2(500),
    FOREIGN KEY (id_vuelo) REFERENCES vuelos(id_vuelo),
    FOREIGN KEY (solicitado_por) REFERENCES empleados(id_empleado),
    FOREIGN KEY (aprobado_por) REFERENCES empleados(id_empleado)
);

-- Tabla 22.4: surtidores_combustible
CREATE TABLE surtidores_combustible (
    id_surtidor NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    codigo_surtidor VARCHAR2(20) UNIQUE NOT NULL,
    ubicacion VARCHAR2(100) NOT NULL,
    tipo_combustible VARCHAR2(20),
    velocidad_carga_litros_hora NUMBER,
    disponible NUMBER(1) DEFAULT 1,
    fecha_ultimo_mantenimiento DATE,
    fecha_proximo_mantenimiento DATE,
    operativo NUMBER(1) DEFAULT 1,
    observaciones VARCHAR2(500)
);

-- Tabla 22.5: cargas_combustible
CREATE TABLE cargas_combustible (
    id_carga_combustible NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_pedido_combustible NUMBER NOT NULL,
    id_surtidor NUMBER,
    cantidad_real_litros NUMBER(15,2) NOT NULL,
    temperatura_combustible NUMBER(5,2),
    densidad_combustible NUMBER(5,4),
    fecha_inicio_carga TIMESTAMP,
    fecha_fin_carga TIMESTAMP,
    duracion_minutos NUMBER,
    operador_carga NUMBER,
    verificador NUMBER,
    lectura_inicial_contador NUMBER(15,2),
    lectura_final_contador NUMBER(15,2),
    incidencia_tecnica NUMBER(1) DEFAULT 0,
    observaciones VARCHAR2(500),
    FOREIGN KEY (id_pedido_combustible) REFERENCES pedidos_combustible(id_pedido_combustible),
    FOREIGN KEY (id_surtidor) REFERENCES surtidores_combustible(id_surtidor),
    FOREIGN KEY (operador_carga) REFERENCES empleados(id_empleado),
    FOREIGN KEY (verificador) REFERENCES empleados(id_empleado)
);

-- Tabla 22.6: control_calidad_combustible
CREATE TABLE control_calidad_combustible (
    id_muestra NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_tanque NUMBER,
    fecha_muestra TIMESTAMP DEFAULT SYSTIMESTAMP,
    fecha_analisis TIMESTAMP,
    numero_muestra VARCHAR2(30) UNIQUE,
    tipo_analisis VARCHAR2(50) CHECK (tipo_analisis IN ('RUTINA', 'ESPECIAL', 'POST_MANTENIMIENTO', 'RECLAMO')),
    analista NUMBER,
    densidad_medida NUMBER(5,4),
    temperatura_prueba NUMBER(5,2),
    presencia_agua NUMBER(5,4),
    particulas_suspendidas NUMBER(5,4),
    conductividad NUMBER(10,4),
    resultado VARCHAR2(20) CHECK (resultado IN ('APROBADO', 'RECHAZADO', 'EN_ANALISIS')),
    aprobado_por NUMBER,
    observaciones VARCHAR2(500),
    FOREIGN KEY (id_tanque) REFERENCES tanques_combustible(id_tanque),
    FOREIGN KEY (analista) REFERENCES empleados(id_empleado),
    FOREIGN KEY (aprobado_por) REFERENCES empleados(id_empleado)
);

-- Tabla 22.7: historial_precios_combustible
CREATE TABLE historial_precios_combustible (
    id_precio_combustible NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    fecha_precio DATE NOT NULL,
    tipo_combustible VARCHAR2(20) NOT NULL,
    precio_compra_local NUMBER(10,4),
    precio_venta_aerolineas NUMBER(10,4),
    moneda VARCHAR2(3),
    precio_internacional_referencia NUMBER(10,4),
    variacion_porcentual NUMBER(5,2),
    factor_ajuste NUMBER(5,4),
    vigente NUMBER(1) DEFAULT 1
);

-- Tabla 22.8: facturacion_combustible
CREATE TABLE facturacion_combustible (
    id_factura_combustible NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_carga_combustible NUMBER NOT NULL,
    numero_factura VARCHAR2(30) UNIQUE NOT NULL,
    id_aerolinea NUMBER NOT NULL,
    fecha_emision DATE DEFAULT SYSDATE,
    cantidad_litros NUMBER(15,2),
    precio_unitario NUMBER(10,4),
    subtotal NUMBER(15,2),
    impuestos NUMBER(15,2),
    total NUMBER(15,2),
    moneda VARCHAR2(3),
    fecha_vencimiento DATE,
    pagada NUMBER(1) DEFAULT 0,
    fecha_pago DATE,
    forma_pago VARCHAR2(30),
    FOREIGN KEY (id_carga_combustible) REFERENCES cargas_combustible(id_carga_combustible),
    FOREIGN KEY (id_aerolinea) REFERENCES aerolineas(id_aerolinea)
);

-- Tabla 22.9: inventario_combustible
CREATE TABLE inventario_combustible (
    id_inventario NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_tanque NUMBER NOT NULL,
    fecha_inventario DATE NOT NULL,
    nivel_medido_litros NUMBER(15,2),
    nivel_teorico_litros NUMBER(15,2),
    diferencia_litros NUMBER(15,2),
    porcentaje_diferencia NUMBER(5,2),
    temperatura_promedio NUMBER(5,2),
    tipo_inventario VARCHAR2(20) CHECK (tipo_inventario IN ('DIARIO', 'SEMANAL', 'MENSUAL', 'FISICO')),
    realizado_por NUMBER,
    verificado_por NUMBER,
    observaciones VARCHAR2(500),
    FOREIGN KEY (id_tanque) REFERENCES tanques_combustible(id_tanque),
    FOREIGN KEY (realizado_por) REFERENCES empleados(id_empleado),
    FOREIGN KEY (verificado_por) REFERENCES empleados(id_empleado)
);

-- Tabla 22.10: recepciones_combustible
CREATE TABLE recepciones_combustible (
    id_recepcion NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_proveedor_combustible NUMBER,
    id_tanque NUMBER,
    numero_guia VARCHAR2(30) UNIQUE,
    fecha_recepcion TIMESTAMP DEFAULT SYSTIMESTAMP,
    cantidad_recibida_litros NUMBER(15,2),
    cantidad_facturada_litros NUMBER(15,2),
    temperatura_recepcion NUMBER(5,2),
    densidad_recepcion NUMBER(5,4),
    placa_camion VARCHAR2(20),
    transportista VARCHAR2(100),
    conductor VARCHAR2(100),
    licencia_conductor VARCHAR2(30),
    inspector_recibe NUMBER,
    certificado_calidad BLOB,
    observaciones VARCHAR2(500),
    FOREIGN KEY (id_proveedor_combustible) REFERENCES proveedores_combustible(id_proveedor_combustible),
    FOREIGN KEY (id_tanque) REFERENCES tanques_combustible(id_tanque),
    FOREIGN KEY (inspector_recibe) REFERENCES empleados(id_empleado)
);

-- =====================================================
-- MÓDULO 23: GESTIÓN AMBIENTAL (9 TABLAS - 23.2 a 23.10)
-- =====================================================

-- Tabla 23.2: monitoreo_ruido
CREATE TABLE monitoreo_ruido (
    id_medicion_ruido NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_estacion_ambiental NUMBER NOT NULL,
    fecha_hora_medicion TIMESTAMP DEFAULT SYSTIMESTAMP,
    nivel_ruido_continua_db NUMBER(5,2),
    nivel_ruido_maximo_db NUMBER(5,2),
    nivel_ruido_minimo_db NUMBER(5,2),
    frecuencia_Hz VARCHAR2(50),
    duracion_segundos NUMBER,
    id_vuelo_asociado NUMBER,
    tipo_fuente VARCHAR2(50) CHECK (tipo_fuente IN ('DESPEGUE', 'ATERRIZAJE', 'PRUEBAS', 'VEHICULOS', 'CONSTRUCCION')),
    excede_limite NUMBER(1) DEFAULT 0,
    alerta_generada NUMBER(1) DEFAULT 0,
    FOREIGN KEY (id_estacion_ambiental) REFERENCES estaciones_monitoreo_ambiental(id_estacion_ambiental),
    FOREIGN KEY (id_vuelo_asociado) REFERENCES vuelos(id_vuelo)
);

-- Tabla 23.3: monitoreo_aire
CREATE TABLE monitoreo_aire (
    id_medicion_aire NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_estacion_ambiental NUMBER NOT NULL,
    fecha_hora_medicion TIMESTAMP DEFAULT SYSTIMESTAMP,
    co2_ppm NUMBER(10,2),
    co_ppm NUMBER(10,2),
    nox_ppm NUMBER(10,2),
    so2_ppm NUMBER(10,2),
    particulas_pm10 NUMBER(10,2),
    particulas_pm25 NUMBER(10,2),
    compuestos_organicos_volatiles NUMBER(10,2),
    temperatura_ambiente NUMBER(5,2),
    humedad_relativa NUMBER(5,2),
    presion_atmosferica NUMBER(10,2),
    velocidad_viento NUMBER(5,2),
    direccion_viento VARCHAR2(10),
    indice_calidad_aire NUMBER(3),
    alerta_generada NUMBER(1) DEFAULT 0,
    FOREIGN KEY (id_estacion_ambiental) REFERENCES estaciones_monitoreo_ambiental(id_estacion_ambiental)
);

-- Tabla 23.4: huella_carbono_vuelo
CREATE TABLE huella_carbono_vuelo (
    id_huella_carbono NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_vuelo NUMBER NOT NULL UNIQUE,
    combustible_consumido_litros NUMBER(15,2),
    factor_emision_co2 NUMBER(10,4),
    co2_emitido_kg NUMBER(15,2),
    co2_por_pasajero_kg NUMBER(10,2),
    co2_por_km NUMBER(10,4),
    distancia_vuelo_km NUMBER(10,2),
    categoria_vuelo VARCHAR2(20) CHECK (categoria_vuelo IN ('CORTO', 'MEDIO', 'LARGO')),
    eficiencia_combustible_kg_km NUMBER(10,4),
    fecha_calculo DATE DEFAULT SYSDATE,
    metodo_calculo VARCHAR2(50),
    certificado_compensacion NUMBER(1) DEFAULT 0,
    FOREIGN KEY (id_vuelo) REFERENCES vuelos(id_vuelo)
);

-- Tabla 23.5: programas_compensacion_ambiental
CREATE TABLE programas_compensacion_ambiental (
    id_programa_compensacion NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre_programa VARCHAR2(100) NOT NULL,
    descripcion VARCHAR2(500),
    tipo_programa VARCHAR2(30) CHECK (tipo_programa IN ('REFORESTACION', 'ENERGIA_LIMPIA', 'EDUCACION', 'INVESTIGACION')),
    fecha_inicio DATE,
    fecha_fin DATE,
    inversion_total NUMBER(15,2),
    moneda VARCHAR2(3),
    co2_compensado_estimado_kg NUMBER(15,2),
    entidad_ejecutora VARCHAR2(100),
    activo NUMBER(1) DEFAULT 1,
    contacto_responsable VARCHAR2(100)
);

-- Tabla 23.6: compensaciones_vuelo
CREATE TABLE compensaciones_vuelo (
    id_compensacion_vuelo NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_huella_carbono NUMBER NOT NULL,
    id_programa_compensacion NUMBER NOT NULL,
    fecha_compensacion DATE DEFAULT SYSDATE,
    cantidad_compensada_kg NUMBER(15,2),
    porcentaje_compensado NUMBER(5,2),
    monto_aportado NUMBER(12,2),
    moneda VARCHAR2(3),
    comprobante_compensacion BLOB,
    verificada NUMBER(1) DEFAULT 0,
    FOREIGN KEY (id_huella_carbono) REFERENCES huella_carbono_vuelo(id_huella_carbono),
    FOREIGN KEY (id_programa_compensacion) REFERENCES programas_compensacion_ambiental(id_programa_compensacion)
);

-- Tabla 23.7: gestion_residuos
CREATE TABLE gestion_residuos (
    id_residuo NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    fecha_recoleccion DATE NOT NULL,
    tipo_residuo VARCHAR2(30) CHECK (tipo_residuo IN ('ORGANICO', 'PLASTICO', 'PAPEL', 'VIDRIO', 'METAL', 'PELIGROSO', 'ELECTRONICO', 'BIOSANITARIO')),
    cantidad_kg NUMBER(10,2) NOT NULL,
    origen VARCHAR2(50) CHECK (origen IN ('TERMINAL', 'VUELOS', 'OFICINAS', 'COMERCIAL', 'MANTENIMIENTO')),
    empresa_recolectora VARCHAR2(100),
    tratamiento VARCHAR2(50) CHECK (tratamiento IN ('RECICLAJE', 'COMPOSTAJE', 'INCINERACION', 'RELLENO')),
    certificado_tratamiento VARCHAR2(100),
    costo_tratamiento NUMBER(10,2),
    observaciones VARCHAR2(500)
);

-- Tabla 23.8: certificaciones_ambientales_aeropuerto
CREATE TABLE certificaciones_ambientales_aeropuerto (
    id_certificacion_ambiental NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    codigo_certificacion VARCHAR2(30) UNIQUE,
    nombre_certificacion VARCHAR2(100) NOT NULL,
    entidad_certificadora VARCHAR2(100),
    fecha_obtencion DATE NOT NULL,
    fecha_vencimiento DATE,
    nivel_certificacion VARCHAR2(30),
    alcance VARCHAR2(500),
    documento_certificado BLOB,
    activa NUMBER(1) DEFAULT 1,
    responsable_seguimiento NUMBER,
    observaciones VARCHAR2(500)
);

-- Tabla 23.9: indicadores_desempeno_ambiental
CREATE TABLE indicadores_desempeno_ambiental (
    id_indicador_ambiental NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    anio NUMBER NOT NULL,
    mes NUMBER CHECK (mes BETWEEN 1 AND 12),
    indicador VARCHAR2(50) CHECK (indicador IN ('HUELLA_CARBONO', 'CONSUMO_AGUA', 'CONSUMO_ENERGIA', 'RESIDUOS', 'RUIDO', 'CALIDAD_AIRE')),
    valor_medido NUMBER(15,2),
    unidad_medida VARCHAR2(20),
    valor_objetivo NUMBER(15,2),
    cumplimiento_porcentaje NUMBER(5,2),
    tendencia VARCHAR2(10) CHECK (tendencia IN ('MEJORA', 'ESTABLE', 'DETERIORO')),
    observaciones VARCHAR2(500),
    UNIQUE(anio, mes, indicador)
);

-- Tabla 23.10: proyectos_eficiencia_energetica
CREATE TABLE proyectos_eficiencia_energetica (
    id_proyecto_eficiencia NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre_proyecto VARCHAR2(200) NOT NULL,
    descripcion VARCHAR2(1000),
    tipo_proyecto VARCHAR2(30) CHECK (tipo_proyecto IN ('ILUMINACION', 'CLIMATIZACION', 'ENERGIA_SOLAR', 'EQUIPOS_EFICIENTES', 'OTROS')),
    inversion_total NUMBER(15,2),
    ahorro_energetico_anual_kwh NUMBER(15,2),
    reduccion_co2_anual_kg NUMBER(15,2),
    fecha_inicio DATE,
    fecha_finalizacion DATE,
    periodo_retorno_anios NUMBER(5,2),
    estado VARCHAR2(20) CHECK (estado IN ('PLANEADO', 'EN_EJECUCION', 'COMPLETADO', 'EVALUADO')),
    responsable_proyecto VARCHAR2(100),
    resultados_obtenidos VARCHAR2(1000)
);

-- =====================================================
-- MÓDULO 26: GESTIÓN DOCUMENTAL Y REGULATORIA (10 TABLAS)
-- =====================================================

-- Tabla 26.1: normativas_aplicables
CREATE TABLE normativas_aplicables (
    id_normativa NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    codigo_normativa VARCHAR2(30) UNIQUE NOT NULL,
    titulo_normativa VARCHAR2(200) NOT NULL,
    descripcion CLOB,
    entidad_emisora VARCHAR2(100),
    pais_origen VARCHAR2(50),
    ambito_aplicacion VARCHAR2(30) CHECK (ambito_aplicacion IN ('INTERNACIONAL', 'REGIONAL', 'NACIONAL', 'LOCAL')),
    fecha_publicacion DATE,
    fecha_vigencia DATE,
    fecha_ultima_actualizacion DATE,
    version VARCHAR2(10),
    documento_oficial BLOB,
    url_referencia VARCHAR2(500),
    obligatoria NUMBER(1) DEFAULT 1,
    activa NUMBER(1) DEFAULT 1
);

-- Tabla 26.2: documentos_requeridos_operacion
CREATE TABLE documentos_requeridos_operacion (
    id_documento_requerido NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    tipo_operacion VARCHAR2(30) CHECK (tipo_operacion IN ('VUELO_INTERNACIONAL', 'VUELO_NACIONAL', 'CARGA', 'TRANSITO', 'PRIVADO')),
    nombre_documento VARCHAR2(100) NOT NULL,
    descripcion VARCHAR2(500),
    obligatorio NUMBER(1) DEFAULT 1,
    formato_aceptado VARCHAR2(100),
    entidad_emisora_requerida VARCHAR2(100),
    periodo_validez_dias NUMBER,
    requiere_original NUMBER(1) DEFAULT 1,
    activo NUMBER(1) DEFAULT 1
);

-- Tabla 26.3: licencias_operativas_aeropuerto
CREATE TABLE licencias_operativas_aeropuerto (
    id_licencia_operativa NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    codigo_licencia VARCHAR2(50) UNIQUE NOT NULL,
    nombre_licencia VARCHAR2(200) NOT NULL,
    tipo_licencia VARCHAR2(50) CHECK (tipo_licencia IN ('OPERATIVA', 'AMBIENTAL', 'SEGURIDAD', 'SANITARIA', 'CONSTRUCCION')),
    entidad_otorgante VARCHAR2(100),
    fecha_emision DATE NOT NULL,
    fecha_vencimiento DATE,
    fecha_renovacion DATE,
    alcance VARCHAR2(1000),
    restricciones VARCHAR2(1000),
    documento_licencia BLOB,
    responsable_seguimiento NUMBER,
    renovacion_automatica NUMBER(1) DEFAULT 0,
    activa NUMBER(1) DEFAULT 1,
    observaciones VARCHAR2(500),
    FOREIGN KEY (responsable_seguimiento) REFERENCES empleados(id_empleado)
);

-- Tabla 26.4: cumplimiento_normativo
CREATE TABLE cumplimiento_normativo (
    id_cumplimiento_normativo NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_normativa NUMBER NOT NULL,
    fecha_verificacion DATE DEFAULT SYSDATE,
    periodo_verificado VARCHAR2(20) CHECK (periodo_verificado IN ('TRIMESTRAL', 'SEMESTRAL', 'ANUAL')),
    responsable_verificacion NUMBER NOT NULL,
    cumplimiento_porcentaje NUMBER(5,2),
    hallazgos CLOB,
    acciones_correctivas CLOB,
    fecha_cierre_acciones DATE,
    evidencia_cumplimiento BLOB,
    calificacion VARCHAR2(20) CHECK (calificacion IN ('EXCELENTE', 'ACEPTABLE', 'OBSERVADO', 'NO_CUMPLE')),
    proxima_verificacion DATE,
    verificacion_completada NUMBER(1) DEFAULT 0,
    FOREIGN KEY (id_normativa) REFERENCES normativas_aplicables(id_normativa),
    FOREIGN KEY (responsable_verificacion) REFERENCES empleados(id_empleado)
);

-- Tabla 26.5: contratos
CREATE TABLE contratos (
    id_contrato NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    numero_contrato VARCHAR2(50) UNIQUE NOT NULL,
    nombre_contrato VARCHAR2(200) NOT NULL,
    tipo_contrato VARCHAR2(30) CHECK (tipo_contrato IN ('CONCESION', 'ARRENDAMIENTO', 'SERVICIOS', 'SUMINISTRO', 'LABORAL')),
    contraparte_nombre VARCHAR2(200) NOT NULL,
    contraparte_documento VARCHAR2(50),
    fecha_firma DATE NOT NULL,
    fecha_inicio DATE NOT NULL,
    fecha_fin DATE NOT NULL,
    fecha_terminacion_anticipada DATE,
    monto_total NUMBER(15,2),
    moneda VARCHAR2(3),
    forma_pago VARCHAR2(200),
    objeto_contractual CLOB,
    clausulas_principales CLOB,
    documento_contrato BLOB,
    renovacion_automatica NUMBER(1) DEFAULT 0,
    notificar_vencimiento_dias NUMBER DEFAULT 30,
    estado VARCHAR2(20) DEFAULT 'VIGENTE' CHECK (estado IN ('VIGENTE', 'VENCIDO', 'TERMINADO', 'SUSPENDIDO', 'RENOVACION')),
    administrador_contrato NUMBER,
    observaciones VARCHAR2(1000),
    FOREIGN KEY (administrador_contrato) REFERENCES empleados(id_empleado)
);

-- Tabla 26.6: clausulas_contrato
CREATE TABLE clausulas_contrato (
    id_clausula_contrato NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_contrato NUMBER NOT NULL,
    numero_clausula NUMBER NOT NULL,
    titulo_clausula VARCHAR2(200),
    texto_clausula CLOB NOT NULL,
    tipo_clausula VARCHAR2(30) CHECK (tipo_clausula IN ('OBLIGACION', 'DERECHO', 'GARANTIA', 'PENALIZACION', 'CONFIDENCIALIDAD')),
    vigente NUMBER(1) DEFAULT 1,
    UNIQUE(id_contrato, numero_clausula),
    FOREIGN KEY (id_contrato) REFERENCES contratos(id_contrato)
);

-- Tabla 26.7: notificaciones_legales
CREATE TABLE notificaciones_legales (
    id_notificacion_legal NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    numero_notificacion VARCHAR2(50) UNIQUE NOT NULL,
    remitente_nombre VARCHAR2(200) NOT NULL,
    remitente_tipo VARCHAR2(30) CHECK (remitente_tipo IN ('ENTIDAD_GUBERNAMENTAL', 'AEROLINEA', 'PASAJERO', 'PROVEEDOR', 'EMPLEADO')),
    destinatario_interno NUMBER,
    asunto VARCHAR2(300) NOT NULL,
    descripcion CLOB,
    fecha_recepcion TIMESTAMP DEFAULT SYSTIMESTAMP,
    fecha_respuesta_requerida DATE,
    prioridad VARCHAR2(20) CHECK (prioridad IN ('BAJA', 'MEDIA', 'ALTA', 'URGENTE')),
    documento_recibido BLOB,
    area_responsable NUMBER,
    usuario_asignado NUMBER,
    estado VARCHAR2(30) DEFAULT 'RECIBIDO' CHECK (estado IN ('RECIBIDO', 'EN_PROCESO', 'RESPONDIDO', 'ARCHIVADO')),
    fecha_respuesta TIMESTAMP,
    respuesta CLOB,
    documento_respuesta BLOB,
    FOREIGN KEY (destinatario_interno) REFERENCES empleados(id_empleado),
    FOREIGN KEY (area_responsable) REFERENCES departamentos(id_departamento),
    FOREIGN KEY (usuario_asignado) REFERENCES empleados(id_empleado)
);

-- Tabla 26.8: documentos_importantes
CREATE TABLE documentos_importantes (
    id_documento_importante NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    codigo_documento VARCHAR2(50) UNIQUE NOT NULL,
    titulo VARCHAR2(200) NOT NULL,
    tipo_documento VARCHAR2(50) CHECK (tipo_documento IN ('ACTA', 'INFORME', 'ESTUDIO', 'PLANO', 'MANUAL', 'POLITICA', 'PROCEDIMIENTO')),
    fecha_creacion DATE DEFAULT SYSDATE,
    fecha_revision DATE,
    version VARCHAR2(10),
    autor VARCHAR2(100),
    area_responsable NUMBER,
    palabras_clave VARCHAR2(500),
    resumen CLOB,
    archivo_digital BLOB,
    ubicacion_fisica VARCHAR2(200),
    confidencial NUMBER(1) DEFAULT 0,
    niveles_acceso VARCHAR2(100),
    activo NUMBER(1) DEFAULT 1,
    FOREIGN KEY (area_responsable) REFERENCES departamentos(id_departamento)
);

-- Tabla 26.9: revisiones_documentos
CREATE TABLE revisiones_documentos (
    id_revision_documento NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_documento_importante NUMBER NOT NULL,
    numero_revision NUMBER NOT NULL,
    fecha_revision DATE DEFAULT SYSDATE,
    revisor NUMBER NOT NULL,
    cambios_realizados CLOB,
    version_resultante VARCHAR2(10),
    aprobado NUMBER(1) DEFAULT 0,
    aprobado_por NUMBER,
    fecha_aprobacion DATE,
    observaciones VARCHAR2(1000),
    UNIQUE(id_documento_importante, numero_revision),
    FOREIGN KEY (id_documento_importante) REFERENCES documentos_importantes(id_documento_importante),
    FOREIGN KEY (revisor) REFERENCES empleados(id_empleado),
    FOREIGN KEY (aprobado_por) REFERENCES empleados(id_empleado)
);

-- Tabla 26.10: auditorias_internas
CREATE TABLE auditorias_internas (
    id_auditoria_interna NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    codigo_auditoria VARCHAR2(30) UNIQUE NOT NULL,
    titulo VARCHAR2(200) NOT NULL,
    tipo_auditoria VARCHAR2(30) CHECK (tipo_auditoria IN ('PROCESOS', 'FINANCIERA', 'SEGURIDAD', 'CALIDAD', 'AMBIENTAL', 'CUMPLIMIENTO')),
    alcance CLOB NOT NULL,
    fecha_inicio_planeacion DATE,
    fecha_fin_planeacion DATE,
    fecha_inicio_ejecucion DATE,
    fecha_fin_ejecucion DATE,
    fecha_informe DATE,
    auditor_lider NUMBER,
    equipo_auditor VARCHAR2(500),
    areas_auditadas VARCHAR2(500),
    hallazgos CLOB,
    no_conformidades CLOB,
    oportunidades_mejora CLOB,
    conclusiones CLOB,
    informe_final BLOB,
    estado VARCHAR2(20) DEFAULT 'PLANEADA' CHECK (estado IN ('PLANEADA', 'EN_EJECUCION', 'EN_INFORME', 'COMPLETADA', 'CANCELADA')),
    FOREIGN KEY (auditor_lider) REFERENCES empleados(id_empleado)
);

-- =====================================================
-- MÓDULO 28: GESTIÓN DE EMERGENCIAS (10 TABLAS)
-- =====================================================

-- Tabla 28.1: planes_emergencia
CREATE TABLE planes_emergencia (
    id_plan_emergencia NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    codigo_plan VARCHAR2(30) UNIQUE NOT NULL,
    nombre_plan VARCHAR2(200) NOT NULL,
    tipo_emergencia VARCHAR2(50) CHECK (tipo_emergencia IN ('INCENDIO', 'TERREMOTO', 'ACCIDENTE_AEREO', 'ATENTADO', 'DERRAME_QUIMICO', 'EMERGENCIA_MEDICA_MASIVA', 'CLIMATICA')),
    nivel_activacion VARCHAR2(30) CHECK (nivel_activacion IN ('PREALERTA', 'ALERTA', 'EMERGENCIA', 'CRISIS')),
    descripcion CLOB NOT NULL,
    procedimiento CLOB NOT NULL,
    responsable_activacion VARCHAR2(200),
    tiempo_respuesta_estimado_minutos NUMBER,
    recursos_requeridos CLOB,
    version VARCHAR2(10),
    fecha_creacion DATE DEFAULT SYSDATE,
    fecha_ultima_revision DATE,
    fecha_proxima_revision DATE,
    documento_plan BLOB,
    activo NUMBER(1) DEFAULT 1
);

-- Tabla 28.2: equipos_emergencia
CREATE TABLE equipos_emergencia (
    id_equipo_emergencia NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    codigo_equipo VARCHAR2(30) UNIQUE NOT NULL,
    nombre_equipo VARCHAR2(100) NOT NULL,
    tipo_equipo VARCHAR2(50) CHECK (tipo_equipo IN ('AMBULANCIA', 'CAMION_BOMBA', 'UNIDAD_RESCATE', 'EQUIPO_MEDICO', 'GENERADOR', 'ILUMINACION', 'COMUNICACIONES')),
    descripcion VARCHAR2(500),
    ubicacion_habitual VARCHAR2(100),
    disponible_24h NUMBER(1) DEFAULT 1,
    personal_asignado NUMBER,
    estado VARCHAR2(20) DEFAULT 'DISPONIBLE' CHECK (estado IN ('DISPONIBLE', 'EN_MANTENIMIENTO', 'EN_USO', 'FUERA_SERVICIO')),
    fecha_ultimo_mantenimiento DATE,
    fecha_proximo_mantenimiento DATE,
    activo NUMBER(1) DEFAULT 1
);

-- Tabla 28.3: personal_emergencia
CREATE TABLE personal_emergencia (
    id_personal_emergencia NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_empleado NUMBER UNIQUE,
    especialidad VARCHAR2(50) CHECK (especialidad IN ('BOMBERO', 'PARAMEDICO', 'MEDICO', 'ENFERMERO', 'RESCATISTA', 'COMUNICADOR', 'COORDINADOR')),
    nivel_certificacion VARCHAR2(30) CHECK (nivel_certificacion IN ('BASICO', 'INTERMEDIO', 'AVANZADO', 'INSTRUCTOR')),
    fecha_certificacion DATE,
    fecha_vencimiento_certificacion DATE,
    disponible_24h NUMBER(1) DEFAULT 0,
    grupo_respuesta VARCHAR2(50),
    activo NUMBER(1) DEFAULT 1,
    FOREIGN KEY (id_empleado) REFERENCES empleados(id_empleado)
);

-- Tabla 28.4: simulacros
CREATE TABLE simulacros (
    id_simulacro NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    fecha_simulacro DATE NOT NULL,
    tipo_simulacro VARCHAR2(50) CHECK (tipo_simulacro IN ('INCENDIO', 'EVACUACION', 'ACCIDENTE_AEREO', 'DERRAME_QUIMICO', 'ATENTADO', 'EMERGENCIA_MEDICA')),
    id_plan_emergencia NUMBER,
    alcance VARCHAR2(500),
    participantes NUMBER,
    duracion_horas NUMBER,
    objetivos CLOB,
    resultados CLOB,
    observaciones CLOB,
    evaluacion VARCHAR2(20) CHECK (evaluacion IN ('SATISFACTORIO', 'MEJORABLE', 'INSUFICIENTE')),
    coordinador VARCHAR2(100),
    fecha_proximo_simulacro DATE,
    FOREIGN KEY (id_plan_emergencia) REFERENCES planes_emergencia(id_plan_emergencia)
);

-- Tabla 28.5: activaciones_emergencia
CREATE TABLE activaciones_emergencia (
    id_activacion NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    fecha_hora_activacion TIMESTAMP DEFAULT SYSTIMESTAMP,
    tipo_emergencia VARCHAR2(50) NOT NULL,
    id_plan_emergencia NUMBER,
    nivel_activacion VARCHAR2(30) CHECK (nivel_activacion IN ('PREALERTA', 'ALERTA', 'EMERGENCIA', 'CRISIS')),
    descripcion_incidente CLOB NOT NULL,
    lugar_incidente VARCHAR2(200),
    personas_afectadas NUMBER,
    personas_atendidas NUMBER,
    recursos_movilizados CLOB,
    hora_control TIMESTAMP,
    hora_fin TIMESTAMP,
    estado VARCHAR2(20) DEFAULT 'ACTIVA' CHECK (estado IN ('ACTIVA', 'FINALIZADA')),
    responsable_coordinacion VARCHAR2(100),
    informe_incidente CLOB,
    lecciones_aprendidas CLOB,
    FOREIGN KEY (id_plan_emergencia) REFERENCES planes_emergencia(id_plan_emergencia)
);

-- Tabla 28.6: puntos_encuentro
CREATE TABLE puntos_encuentro (
    id_punto_encuentro NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    codigo_punto VARCHAR2(20) UNIQUE NOT NULL,
    nombre VARCHAR2(100) NOT NULL,
    ubicacion VARCHAR2(200) NOT NULL,
    coordenada_latitud NUMBER(10,6),
    coordenada_longitud NUMBER(10,6),
    capacidad_personas NUMBER,
    senalizacion_visible NUMBER(1) DEFAULT 1,
    iluminacion NUMBER(1) DEFAULT 1,
    recursos_disponibles VARCHAR2(500),
    responsable_asignado VARCHAR2(100),
    activo NUMBER(1) DEFAULT 1
);

-- Tabla 28.7: comunicaciones_emergencia
CREATE TABLE comunicaciones_emergencia (
    id_comunicacion_emergencia NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_activacion NUMBER,
    fecha_hora_envio TIMESTAMP DEFAULT SYSTIMESTAMP,
    tipo_mensaje VARCHAR2(30) CHECK (tipo_mensaje IN ('ALERTA', 'INSTRUCCION', 'INFORME', 'EVACUACION', 'CONFIRMACION')),
    medio_envio VARCHAR2(30) CHECK (medio_envio IN ('ALTAVOZ', 'SMS', 'EMAIL', 'RADIO', 'APP', 'MEGAFONO')),
    destinatarios VARCHAR2(1000),
    contenido CLOB NOT NULL,
    emisor VARCHAR2(100),
    confirmacion_recibido NUMBER(1) DEFAULT 0,
    observaciones VARCHAR2(500),
    FOREIGN KEY (id_activacion) REFERENCES activaciones_emergencia(id_activacion)
);

-- Tabla 28.8: recursos_emergencia
CREATE TABLE recursos_emergencia (
    id_recurso_emergencia NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    tipo_recurso VARCHAR2(50) CHECK (tipo_recurso IN ('MEDICO', 'EXTINCION', 'RESCATE', 'COMUNICACION', 'TRANSPORTE', 'ENERGIA', 'AGUA', 'ALIMENTOS')),
    nombre_recurso VARCHAR2(100) NOT NULL,
    cantidad_disponible NUMBER DEFAULT 0,
    ubicacion_almacen VARCHAR2(100),
    fecha_vencimiento DATE,
    proveedor VARCHAR2(100),
    responsable_mantenimiento VARCHAR2(100),
    fecha_ultima_revision DATE,
    fecha_proxima_revision DATE,
    activo NUMBER(1) DEFAULT 1
);

-- Tabla 28.9: evaluaciones_post_emergencia
CREATE TABLE evaluaciones_post_emergencia (
    id_evaluacion_post NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_activacion NUMBER NOT NULL,
    fecha_evaluacion TIMESTAMP DEFAULT SYSTIMESTAMP,
    evaluador VARCHAR2(100) NOT NULL,
    tiempo_respuesta_minutos NUMBER,
    eficacia_respuesta NUMBER(1) CHECK (eficacia_respuesta BETWEEN 1 AND 5),
    coordinacion NUMBER(1) CHECK (coordinacion BETWEEN 1 AND 5),
    recursos_utilizados CLOB,
    puntos_fuertes CLOB,
    areas_mejora CLOB,
    acciones_recomendadas CLOB,
    responsable_seguimiento VARCHAR2(100),
    fecha_seguimiento DATE,
    FOREIGN KEY (id_activacion) REFERENCES activaciones_emergencia(id_activacion)
);

-- Tabla 28.10: entrenamientos_emergencia
CREATE TABLE entrenamientos_emergencia (
    id_entrenamiento NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre_entrenamiento VARCHAR2(200) NOT NULL,
    tipo_entrenamiento VARCHAR2(50) CHECK (tipo_entrenamiento IN ('PRIMEROS_AUXILIOS', 'COMBATE_INCENDIOS', 'EVACUACION', 'MAT_PELIGROSOS', 'COMUNICACIONES', 'COORDINACION')),
    fecha_realizacion DATE NOT NULL,
    duracion_horas NUMBER,
    instructor VARCHAR2(100),
    participantes NUMBER,
    contenido CLOB,
    evaluacion CLOB,
    certificaciones_entregadas NUMBER(1) DEFAULT 0,
    fecha_proximo_entrenamiento DATE
);

-- =====================================================
-- GRUPO 6: SISTEMAS, MONITOREO Y CUMPLIMIENTO GLOBAL
-- =====================================================

-- =====================================================
-- MÓDULO 21: OPERACIONES EN TIEMPO REAL (10 TABLAS)
-- =====================================================

-- Tabla 21.1: posiciones_radar
CREATE TABLE posiciones_radar (
    id_posicion_radar NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_vuelo NUMBER NOT NULL,
    timestamp_posicion TIMESTAMP DEFAULT SYSTIMESTAMP,
    latitud NUMBER(10,6) NOT NULL,
    longitud NUMBER(10,6) NOT NULL,
    altitud_pies NUMBER,
    velocidad_nudos NUMBER,
    heading_grados NUMBER,
    tasa_ascenso NUMBER,
    fuente_datos VARCHAR2(30) CHECK (fuente_datos IN ('RADAR', 'ADS-B', 'MLAT', 'SATELITE')),
    precision_posicion NUMBER(3),
    procesado NUMBER(1) DEFAULT 0,
    FOREIGN KEY (id_vuelo) REFERENCES vuelos(id_vuelo)
);

-- Tabla 21.2: torre_control_comunicaciones
CREATE TABLE torre_control_comunicaciones (
    id_comunicacion_torre NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_vuelo NUMBER NOT NULL,
    timestamp_comunicacion TIMESTAMP DEFAULT SYSTIMESTAMP,
    frecuencia_mhz VARCHAR2(10),
    tipo_comunicacion VARCHAR2(30) CHECK (tipo_comunicacion IN ('AUTORIZACION', 'DESPEGUE', 'ATERRIZAJE', 'EMERGENCIA', 'INFORMACION', 'CONSULTA')),
    origen VARCHAR2(50),
    destino VARCHAR2(50),
    mensaje VARCHAR2(1000) NOT NULL,
    operador_torre NUMBER,
    grabacion_audio BLOB,
    transcrito NUMBER(1) DEFAULT 0,
    FOREIGN KEY (id_vuelo) REFERENCES vuelos(id_vuelo),
    FOREIGN KEY (operador_torre) REFERENCES empleados(id_empleado)
);

-- Tabla 21.3: asignacion_pistas_tiempo_real
CREATE TABLE asignacion_pistas_tiempo_real (
    id_asignacion_pista NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_pista NUMBER NOT NULL,
    id_vuelo NUMBER NOT NULL,
    tipo_operacion VARCHAR2(20) CHECK (tipo_operacion IN ('DESPEGUE', 'ATERRIZAJE')),
    fecha_hora_asignacion TIMESTAMP DEFAULT SYSTIMESTAMP,
    hora_inicio_estimada TIMESTAMP NOT NULL,
    hora_fin_estimada TIMESTAMP NOT NULL,
    hora_inicio_real TIMESTAMP,
    hora_fin_real TIMESTAMP,
    estado_asignacion VARCHAR2(30) DEFAULT 'PROGRAMADA' CHECK (estado_asignacion IN ('PROGRAMADA', 'ACTIVA', 'COMPLETADA', 'CANCELADA')),
    asignado_por NUMBER,
    observaciones VARCHAR2(500),
    FOREIGN KEY (id_pista) REFERENCES pistas_aterrizaje(id_pista),
    FOREIGN KEY (id_vuelo) REFERENCES vuelos(id_vuelo),
    FOREIGN KEY (asignado_por) REFERENCES empleados(id_empleado)
);

-- Tabla 21.4: condiciones_pista_tiempo_real
CREATE TABLE condiciones_pista_tiempo_real (
    id_condicion_pista NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_pista NUMBER NOT NULL,
    fecha_hora_registro TIMESTAMP DEFAULT SYSTIMESTAMP,
    estado_pista VARCHAR2(30) CHECK (estado_pista IN ('OPERATIVA', 'EN_MANTENIMIENTO', 'CERRADA', 'LIMITADA')),
    condicion_superficie VARCHAR2(30) CHECK (condicion_superficie IN ('SECA', 'MOJADA', 'HIELO', 'NIEVE', 'ACEITE')),
    coeficiente_friccion NUMBER(3,2),
    visibilidad_metros NUMBER,
    techonubes_pies NUMBER,
    viento_direccion_grados NUMBER,
    viento_velocidad_nudos NUMBER,
    observaciones VARCHAR2(500),
    registrado_por NUMBER,
    FOREIGN KEY (id_pista) REFERENCES pistas_aterrizaje(id_pista),
    FOREIGN KEY (registrado_por) REFERENCES empleados(id_empleado)
);

-- Tabla 21.5: slots_aeropuerto
CREATE TABLE slots_aeropuerto (
    id_slot NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_aerolinea NUMBER NOT NULL,
    fecha_slot DATE NOT NULL,
    hora_slot TIMESTAMP NOT NULL,
    tipo_operacion VARCHAR2(20) CHECK (tipo_operacion IN ('DESPEGUE', 'ATERRIZAJE')),
    id_vuelo_asignado NUMBER,
    estado_slot VARCHAR2(30) DEFAULT 'DISPONIBLE' CHECK (estado_slot IN ('DISPONIBLE', 'ASIGNADO', 'UTILIZADO', 'CANCELADO')),
    fecha_asignacion TIMESTAMP,
    asignado_por NUMBER,
    fecha_liberacion TIMESTAMP,
    motivo_cancelacion VARCHAR2(500),
    FOREIGN KEY (id_aerolinea) REFERENCES aerolineas(id_aerolinea),
    FOREIGN KEY (id_vuelo_asignado) REFERENCES vuelos(id_vuelo)
);

-- Tabla 21.6: retrasos_tiempo_real
CREATE TABLE retrasos_tiempo_real (
    id_retraso_tiempo_real NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_vuelo NUMBER NOT NULL,
    fecha_hora_registro TIMESTAMP DEFAULT SYSTIMESTAMP,
    tipo_retraso VARCHAR2(30) CHECK (tipo_retraso IN ('CLIMATICO', 'TECNICO', 'OPERACIONAL', 'TRANSITO', 'TRIPULACION', 'SEGURIDAD', 'OTROS')),
    causa_especifica VARCHAR2(500),
    minutos_retraso_actuales NUMBER,
    minutos_retraso_estimados NUMBER,
    impacto_global NUMBER(1) DEFAULT 0,
    afecta_conexiones NUMBER(1) DEFAULT 0,
    notificado_pasajeros NUMBER(1) DEFAULT 0,
    actualizado_por NUMBER,
    observaciones VARCHAR2(500),
    FOREIGN KEY (id_vuelo) REFERENCES vuelos(id_vuelo),
    FOREIGN KEY (actualizado_por) REFERENCES empleados(id_empleado)
);

-- Tabla 21.7: capacidad_terminal_tiempo_real
CREATE TABLE capacidad_terminal_tiempo_real (
    id_medicion_terminal NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    terminal VARCHAR2(10) NOT NULL,
    fecha_hora_medicion TIMESTAMP DEFAULT SYSTIMESTAMP,
    pasajeros_actuales NUMBER,
    pasajeros_estimados_salida NUMBER,
    pasajeros_estimados_llegada NUMBER,
    pasajeros_en_transito NUMBER,
    capacidad_maxima NUMBER,
    porcentaje_ocupacion NUMBER(5,2),
    nivel_congestion VARCHAR2(20) CHECK (nivel_congestion IN ('BAJO', 'MODERADO', 'ALTO', 'CRITICO')),
    tiempo_espera_seguridad_minutos NUMBER,
    medicion_automatica NUMBER(1) DEFAULT 0,
    registrado_por NUMBER
);

-- Tabla 21.8: alertas_operacionales
CREATE TABLE alertas_operacionales (
    id_alerta_operacional NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    tipo_alerta VARCHAR2(50) CHECK (tipo_alerta IN ('CONGESTION', 'RETRASO_GENERAL', 'INCIDENTE', 'CLIMA_SEVERO', 'FALLA_TECNICA')),
    nivel_alerta VARCHAR2(20) CHECK (nivel_alerta IN ('INFORMATIVO', 'PREVENTIVO', 'CRITICO')),
    descripcion VARCHAR2(500) NOT NULL,
    fecha_hora_inicio TIMESTAMP DEFAULT SYSTIMESTAMP,
    fecha_hora_fin TIMESTAMP,
    area_afectada VARCHAR2(100),
    vuelos_afectados NUMBER,
    pasajeros_afectados NUMBER,
    acciones_recomendadas VARCHAR2(1000),
    activa NUMBER(1) DEFAULT 1,
    creada_por NUMBER,
    cerrada_por NUMBER,
    FOREIGN KEY (creada_por) REFERENCES empleados(id_empleado),
    FOREIGN KEY (cerrada_por) REFERENCES empleados(id_empleado)
);

-- Tabla 21.9: historial_flujo_trafico
CREATE TABLE historial_flujo_trafico (
    id_flujo NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    fecha_hora_inicio TIMESTAMP NOT NULL,
    fecha_hora_fin TIMESTAMP,
    tipo_medicion VARCHAR2(30) CHECK (tipo_medicion IN ('POR_HORA', 'POR_DIA', 'POR_SEMANA')),
    despegues_hora NUMBER,
    aterrizajes_hora NUMBER,
    total_operaciones_hora NUMBER,
    pasajeros_salida_hora NUMBER,
    pasajeros_llegada_hora NUMBER,
    total_pasajeros_hora NUMBER,
    pico_operaciones NUMBER(1) DEFAULT 0,
    observaciones VARCHAR2(500)
);

-- Tabla 21.10: prediccion_demanda
CREATE TABLE prediccion_demanda (
    id_prediccion NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    fecha_prediccion DATE NOT NULL,
    hora_prediccion TIMESTAMP,
    tipo_prediccion VARCHAR2(30) CHECK (tipo_prediccion IN ('OPERACIONES', 'PASAJEROS', 'CARGA')),
    valor_predicho NUMBER(15,2),
    intervalo_confianza_inferior NUMBER(15,2),
    intervalo_confianza_superior NUMBER(15,2),
    modelo_utilizado VARCHAR2(100),
    precision_historica NUMBER(5,2),
    fecha_generacion TIMESTAMP DEFAULT SYSTIMESTAMP,
    generado_por VARCHAR2(50)
);

-- =====================================================
-- MÓDULO 24: SEGURIDAD INFORMÁTICA Y ACCESOS (12 TABLAS)
-- =====================================================

-- Tabla 24.1: usuarios_sistema
CREATE TABLE usuarios_sistema (
    id_usuario_sistema NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_empleado NUMBER UNIQUE,
    nombre_usuario VARCHAR2(50) UNIQUE NOT NULL,
    password_hash VARCHAR2(255) NOT NULL,
    email_institucional VARCHAR2(100) UNIQUE,
    fecha_creacion DATE DEFAULT SYSDATE,
    fecha_ultimo_acceso TIMESTAMP,
    fecha_vencimiento_password DATE,
    intentos_fallidos NUMBER DEFAULT 0,
    bloqueado NUMBER(1) DEFAULT 0,
    motivo_bloqueo VARCHAR2(200),
    requiere_cambio_password NUMBER(1) DEFAULT 0,
    activo NUMBER(1) DEFAULT 1,
    creado_por NUMBER,
    FOREIGN KEY (id_empleado) REFERENCES empleados(id_empleado),
    FOREIGN KEY (creado_por) REFERENCES usuarios_sistema(id_usuario_sistema)
);

-- Tabla 24.2: roles_sistema
CREATE TABLE roles_sistema (
    id_rol_sistema NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre_rol VARCHAR2(50) UNIQUE NOT NULL,
    descripcion VARCHAR2(200),
    nivel_jerarquico NUMBER,
    activo NUMBER(1) DEFAULT 1
);

-- Tabla 24.3: usuarios_roles (clave compuesta)
CREATE TABLE usuarios_roles (
    id_usuario_sistema NUMBER,
    id_rol_sistema NUMBER,
    fecha_asignacion DATE DEFAULT SYSDATE,
    asignado_por NUMBER,
    activo NUMBER(1) DEFAULT 1,
    PRIMARY KEY (id_usuario_sistema, id_rol_sistema),
    FOREIGN KEY (id_usuario_sistema) REFERENCES usuarios_sistema(id_usuario_sistema),
    FOREIGN KEY (id_rol_sistema) REFERENCES roles_sistema(id_rol_sistema),
    FOREIGN KEY (asignado_por) REFERENCES usuarios_sistema(id_usuario_sistema)
);

-- Tabla 24.4: modulos_sistema
CREATE TABLE modulos_sistema (
    id_modulo_sistema NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre_modulo VARCHAR2(50) UNIQUE NOT NULL,
    descripcion VARCHAR2(200),
    ruta_acceso VARCHAR2(100),
    icono VARCHAR2(50),
    orden NUMBER,
    activo NUMBER(1) DEFAULT 1
);

-- Tabla 24.5: roles_permisos_modulos (clave compuesta)
CREATE TABLE roles_permisos_modulos (
    id_rol_sistema NUMBER,
    id_modulo_sistema NUMBER,
    permiso_lectura NUMBER(1) DEFAULT 0,
    permiso_escritura NUMBER(1) DEFAULT 0,
    permiso_eliminacion NUMBER(1) DEFAULT 0,
    permiso_ejecucion NUMBER(1) DEFAULT 0,
    PRIMARY KEY (id_rol_sistema, id_modulo_sistema),
    FOREIGN KEY (id_rol_sistema) REFERENCES roles_sistema(id_rol_sistema),
    FOREIGN KEY (id_modulo_sistema) REFERENCES modulos_sistema(id_modulo_sistema)
);

-- Tabla 24.6: logs_acceso_sistema
CREATE TABLE logs_acceso_sistema (
    id_log_acceso NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_usuario_sistema NUMBER,
    timestamp_acceso TIMESTAMP DEFAULT SYSTIMESTAMP,
    ip_origen VARCHAR2(45),
    dispositivo VARCHAR2(100),
    navegador VARCHAR2(100),
    sistema_operativo VARCHAR2(50),
    tipo_acceso VARCHAR2(20) CHECK (tipo_acceso IN ('LOGIN', 'LOGOUT', 'LOGIN_FALLIDO')),
    resultado VARCHAR2(20) CHECK (resultado IN ('EXITOSO', 'FALLIDO', 'BLOQUEADO')),
    sesion_id VARCHAR2(100),
    FOREIGN KEY (id_usuario_sistema) REFERENCES usuarios_sistema(id_usuario_sistema)
);

-- Tabla 24.7: tokens_autenticacion
CREATE TABLE tokens_autenticacion (
    id_token NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_usuario_sistema NUMBER NOT NULL,
    token VARCHAR2(500) UNIQUE NOT NULL,
    tipo_token VARCHAR2(20) CHECK (tipo_token IN ('SESION', 'API', 'RECUPERACION', '2FA')),
    fecha_emision TIMESTAMP DEFAULT SYSTIMESTAMP,
    fecha_expiracion TIMESTAMP NOT NULL,
    ultimo_uso TIMESTAMP,
    ip_creacion VARCHAR2(45),
    dispositivo_creacion VARCHAR2(100),
    revocado NUMBER(1) DEFAULT 0,
    fecha_revocacion TIMESTAMP,
    motivo_revocacion VARCHAR2(200),
    FOREIGN KEY (id_usuario_sistema) REFERENCES usuarios_sistema(id_usuario_sistema)
);

-- Tabla 24.8: bitacora_cambios_db
CREATE TABLE bitacora_cambios_db (
    id_bitacora_cambio NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_usuario_sistema NUMBER,
    timestamp_cambio TIMESTAMP DEFAULT SYSTIMESTAMP,
    tabla_afectada VARCHAR2(50) NOT NULL,
    registro_id NUMBER,
    tipo_operacion VARCHAR2(10) CHECK (tipo_operacion IN ('INSERT', 'UPDATE', 'DELETE')),
    valores_anteriores CLOB,
    valores_nuevos CLOB,
    ip_origen VARCHAR2(45),
    sesion_id VARCHAR2(100),
    FOREIGN KEY (id_usuario_sistema) REFERENCES usuarios_sistema(id_usuario_sistema)
);

-- Tabla 24.9: respaldos_sistema
CREATE TABLE respaldos_sistema (
    id_respaldo NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    fecha_respaldo TIMESTAMP DEFAULT SYSTIMESTAMP,
    tipo_respaldo VARCHAR2(20) CHECK (tipo_respaldo IN ('COMPLETO', 'INCREMENTAL', 'DIFERENCIAL')),
    tamano_mb NUMBER(15,2),
    ubicacion_respaldo VARCHAR2(500),
    nombre_archivo VARCHAR2(200),
    verificado NUMBER(1) DEFAULT 0,
    fecha_verificacion TIMESTAMP,
    realizado_por NUMBER,
    observaciones VARCHAR2(500),
    FOREIGN KEY (realizado_por) REFERENCES usuarios_sistema(id_usuario_sistema)
);

-- Tabla 24.10: incidentes_seguridad_informatica
CREATE TABLE incidentes_seguridad_informatica (
    id_incidente_seguridad_info NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    fecha_deteccion TIMESTAMP DEFAULT SYSTIMESTAMP,
    tipo_incidente VARCHAR2(50) CHECK (tipo_incidente IN ('INTENTO_ACCESO', 'FUERZA_BRUTA', 'MALWARE', 'PHISHING', 'FILTRACION', 'DOS', 'ACCESO_NO_AUTORIZADO')),
    nivel_gravedad VARCHAR2(20) CHECK (nivel_gravedad IN ('BAJO', 'MEDIO', 'ALTO', 'CRITICO')),
    descripcion VARCHAR2(1000) NOT NULL,
    ip_origen VARCHAR2(45),
    usuario_afectado NUMBER,
    acciones_tomadas VARCHAR2(1000),
    fecha_resolucion TIMESTAMP,
    responsable_resolucion NUMBER,
    requiere_notificacion_legal NUMBER(1) DEFAULT 0,
    notificado_legal NUMBER(1) DEFAULT 0,
    estado VARCHAR2(20) DEFAULT 'ACTIVO' CHECK (estado IN ('ACTIVO', 'EN_INVESTIGACION', 'RESUELTO', 'FALSO_POSITIVO')),
    FOREIGN KEY (usuario_afectado) REFERENCES usuarios_sistema(id_usuario_sistema),
    FOREIGN KEY (responsable_resolucion) REFERENCES usuarios_sistema(id_usuario_sistema)
);

-- Tabla 24.11: politicas_seguridad
CREATE TABLE politicas_seguridad (
    id_politica NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre_politica VARCHAR2(100) NOT NULL,
    version VARCHAR2(10),
    fecha_aprobacion DATE,
    fecha_vigencia DATE,
    fecha_revision DATE,
    contenido CLOB,
    aprobado_por NUMBER,
    responsable_ejecucion NUMBER,
    activa NUMBER(1) DEFAULT 1,
    FOREIGN KEY (aprobado_por) REFERENCES usuarios_sistema(id_usuario_sistema),
    FOREIGN KEY (responsable_ejecucion) REFERENCES usuarios_sistema(id_usuario_sistema)
);

-- Tabla 24.12: auditorias_seguridad
CREATE TABLE auditorias_seguridad (
    id_auditoria_seguridad NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    fecha_auditoria DATE DEFAULT SYSDATE,
    tipo_auditoria VARCHAR2(30) CHECK (tipo_auditoria IN ('INTERNA', 'EXTERNA', 'REGULATORIA')),
    entidad_auditora VARCHAR2(100),
    alcance VARCHAR2(1000),
    hallazgos CLOB,
    recomendaciones CLOB,
    fecha_cierre DATE,
    responsable_cierre NUMBER,
    documento_auditoria BLOB,
    estado VARCHAR2(20) DEFAULT 'EN_PROCESO' CHECK (estado IN ('EN_PROCESO', 'COMPLETADA', 'PENDIENTE_ACCION')),
    FOREIGN KEY (responsable_cierre) REFERENCES usuarios_sistema(id_usuario_sistema)
);

-- =====================================================
-- MÓDULO 25: MARKETING Y FIDELIZACIÓN (10 TABLAS)
-- =====================================================

-- Tabla 25.1: campanas_marketing
CREATE TABLE campanas_marketing (
    id_campana_marketing NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre_campana VARCHAR2(200) NOT NULL,
    descripcion VARCHAR2(500),
    tipo_campana VARCHAR2(30) CHECK (tipo_campana IN ('EMAIL', 'SMS', 'REDES_SOCIALES', 'WEB', 'APP', 'PRENSA', 'RADIO', 'TV')),
    objetivo VARCHAR2(50) CHECK (objetivo IN ('VENTAS', 'FIDELIZACION', 'NOTORIEDAD', 'LANZAMIENTO')),
    fecha_inicio DATE NOT NULL,
    fecha_fin DATE NOT NULL,
    presupuesto NUMBER(12,2),
    moneda VARCHAR2(3),
    costo_real NUMBER(12,2),
    publico_objetivo VARCHAR2(500),
    segmento_objetivo VARCHAR2(100),
    activa NUMBER(1) DEFAULT 1,
    responsable NUMBER,
    resultados CLOB,
    FOREIGN KEY (responsable) REFERENCES empleados(id_empleado)
);

-- Tabla 25.2: segmentos_clientes
CREATE TABLE segmentos_clientes (
    id_segmento_cliente NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre_segmento VARCHAR2(100) NOT NULL,
    descripcion VARCHAR2(500),
    criterios_json CLOB,
    frecuencia_viajes VARCHAR2(30) CHECK (frecuencia_viajes IN ('ALTA', 'MEDIA', 'BAJA', 'OCASIONAL')),
    clase_preferida VARCHAR2(20),
    destinos_frecuentes CLOB,
    edad_promedio NUMBER,
    nivel_ingresos VARCHAR2(20),
    activo NUMBER(1) DEFAULT 1
);

-- Tabla 25.3: pasajeros_segmentos (clave compuesta)
CREATE TABLE pasajeros_segmentos (
    id_pasajero NUMBER,
    id_segmento_cliente NUMBER,
    fecha_asignacion DATE DEFAULT SYSDATE,
    automatico NUMBER(1) DEFAULT 0,
    activo NUMBER(1) DEFAULT 1,
    PRIMARY KEY (id_pasajero, id_segmento_cliente),
    FOREIGN KEY (id_pasajero) REFERENCES pasajeros(id_pasajero),
    FOREIGN KEY (id_segmento_cliente) REFERENCES segmentos_clientes(id_segmento_cliente)
);

-- Tabla 25.4: ofertas_personalizadas
CREATE TABLE ofertas_personalizadas (
    id_oferta_personalizada NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_segmento_cliente NUMBER,
    id_promocion NUMBER,
    titulo_oferta VARCHAR2(200) NOT NULL,
    descripcion VARCHAR2(500),
    condiciones VARCHAR2(1000),
    descuento_porcentaje NUMBER(5,2),
    descuento_fijo NUMBER(10,2),
    fecha_inicio DATE NOT NULL,
    fecha_fin DATE NOT NULL,
    prioridad NUMBER,
    visualizaciones NUMBER DEFAULT 0,
    conversiones NUMBER DEFAULT 0,
    activa NUMBER(1) DEFAULT 1,
    creada_por NUMBER,
    FOREIGN KEY (id_segmento_cliente) REFERENCES segmentos_clientes(id_segmento_cliente),
    FOREIGN KEY (id_promocion) REFERENCES promociones(id_promocion),
    FOREIGN KEY (creada_por) REFERENCES empleados(id_empleado)
);

-- Tabla 25.5: canjes_puntos
CREATE TABLE canjes_puntos (
    id_canje_puntos NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_pasajero NUMBER NOT NULL,
    id_lealtad NUMBER NOT NULL,
    fecha_canje TIMESTAMP DEFAULT SYSTIMESTAMP,
    puntos_utilizados NUMBER NOT NULL,
    tipo_canje VARCHAR2(30) CHECK (tipo_canje IN ('VUELO', 'UPGRADE', 'PRODUCTO', 'SERVICIO', 'EQUIPAJE_EXTRA')),
    descripcion_canje VARCHAR2(500),
    id_vuelo NUMBER,
    id_producto NUMBER,
    valor_monetario NUMBER(10,2),
    moneda VARCHAR2(3),
    estado_canje VARCHAR2(20) DEFAULT 'PROCESADO' CHECK (estado_canje IN ('PROCESADO', 'ENTREGADO', 'CANCELADO')),
    procesado_por NUMBER,
    observaciones VARCHAR2(500),
    FOREIGN KEY (id_pasajero) REFERENCES pasajeros(id_pasajero),
    FOREIGN KEY (id_lealtad) REFERENCES programa_lealtad(id_lealtad),
    FOREIGN KEY (id_vuelo) REFERENCES vuelos(id_vuelo),
    FOREIGN KEY (id_producto) REFERENCES tiendas_productos(id_producto),
    FOREIGN KEY (procesado_por) REFERENCES empleados(id_empleado)
);

-- Tabla 25.6: newsletter_suscripciones
CREATE TABLE newsletter_suscripciones (
    id_suscripcion_newsletter NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_pasajero NUMBER,
    email VARCHAR2(100) NOT NULL,
    nombre VARCHAR2(100),
    fecha_suscripcion DATE DEFAULT SYSDATE,
    fecha_baja DATE,
    frecuencia VARCHAR2(20) DEFAULT 'MENSUAL' CHECK (frecuencia IN ('DIARIA', 'SEMANAL', 'MENSUAL', 'TRIMESTRAL')),
    temas_interes VARCHAR2(500),
    confirmado NUMBER(1) DEFAULT 0,
    token_confirmacion VARCHAR2(100),
    activo NUMBER(1) DEFAULT 1,
    FOREIGN KEY (id_pasajero) REFERENCES pasajeros(id_pasajero)
);

-- Tabla 25.7: newsletter_envios
CREATE TABLE newsletter_envios (
    id_envio_newsletter NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_suscripcion_newsletter NUMBER NOT NULL,
    id_campana_marketing NUMBER,
    fecha_envio TIMESTAMP DEFAULT SYSTIMESTAMP,
    asunto VARCHAR2(200),
    contenido CLOB,
    formato VARCHAR2(10) CHECK (formato IN ('HTML', 'TEXTO')),
    abierto NUMBER(1) DEFAULT 0,
    fecha_apertura TIMESTAMP,
    clicks NUMBER DEFAULT 0,
    convertido NUMBER(1) DEFAULT 0,
    FOREIGN KEY (id_suscripcion_newsletter) REFERENCES newsletter_suscripciones(id_suscripcion_newsletter),
    FOREIGN KEY (id_campana_marketing) REFERENCES campanas_marketing(id_campana_marketing)
);

-- Tabla 25.8: encuestas_post_vuelo
CREATE TABLE encuestas_post_vuelo (
    id_encuesta_post_vuelo NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_vuelo NUMBER NOT NULL,
    id_pasajero NUMBER NOT NULL,
    fecha_encuesta TIMESTAMP DEFAULT SYSTIMESTAMP,
    canal_respuesta VARCHAR2(20) CHECK (canal_respuesta IN ('EMAIL', 'SMS', 'APP', 'WEB', 'PRESENCIAL')),
    puntuacion_general NUMBER(1) CHECK (puntuacion_general BETWEEN 1 AND 5),
    puntuacion_checkin NUMBER(1) CHECK (puntuacion_checkin BETWEEN 1 AND 5),
    puntuacion_abordaje NUMBER(1) CHECK (puntuacion_abordaje BETWEEN 1 AND 5),
    puntuacion_tripulacion NUMBER(1) CHECK (puntuacion_tripulacion BETWEEN 1 AND 5),
    puntuacion_comida NUMBER(1) CHECK (puntuacion_comida BETWEEN 1 AND 5),
    puntuacion_confort NUMBER(1) CHECK (puntuacion_confort BETWEEN 1 AND 5),
    puntuacion_puntualidad NUMBER(1) CHECK (puntuacion_puntualidad BETWEEN 1 AND 5),
    comentarios VARCHAR2(2000),
    recomendaria NUMBER(1) CHECK (recomendaria IN (0,1)),
    nps_generado NUMBER(3) CHECK (nps_generado BETWEEN -100 AND 100),
    procesada NUMBER(1) DEFAULT 0,
    FOREIGN KEY (id_vuelo) REFERENCES vuelos(id_vuelo),
    FOREIGN KEY (id_pasajero) REFERENCES pasajeros(id_pasajero)
);

-- Tabla 25.9: analisis_comportamiento
CREATE TABLE analisis_comportamiento (
    id_analisis_comportamiento NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_pasajero NUMBER NOT NULL,
    fecha_analisis DATE DEFAULT SYSDATE,
    vuelos_anio NUMBER DEFAULT 0,
    vuelos_mes NUMBER DEFAULT 0,
    vuelos_semana NUMBER DEFAULT 0,
    destinos_frecuentes VARCHAR2(500),
    aerolineas_preferidas VARCHAR2(500),
    clase_preferida VARCHAR2(20),
    dia_preferido_viaje VARCHAR2(10),
    mes_preferido_viaje NUMBER,
    anticipacion_promedio_reserva NUMBER,
    gasto_promedio_anual NUMBER(12,2),
    gasto_promedio_vuelo NUMBER(10,2),
    ingresos_totales_generados NUMBER(15,2),
    score_fidelidad NUMBER(5,2),
    ultima_actualizacion TIMESTAMP DEFAULT SYSTIMESTAMP,
    FOREIGN KEY (id_pasajero) REFERENCES pasajeros(id_pasajero)
);

-- Tabla 25.10: reacciones_promociones
CREATE TABLE reacciones_promociones (
    id_reaccion NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_oferta_personalizada NUMBER NOT NULL,
    id_pasajero NUMBER NOT NULL,
    fecha_reaccion TIMESTAMP DEFAULT SYSTIMESTAMP,
    tipo_reaccion VARCHAR2(20) CHECK (tipo_reaccion IN ('VISTA', 'CLICK', 'APLICADA', 'COMPARTIDA', 'IGNORADA')),
    canal VARCHAR2(20) CHECK (canal IN ('EMAIL', 'SMS', 'APP', 'WEB')),
    convertido_en_reserva NUMBER(1) DEFAULT 0,
    id_reserva NUMBER,
    valor_conversion NUMBER(10,2),
    FOREIGN KEY (id_oferta_personalizada) REFERENCES ofertas_personalizadas(id_oferta_personalizada),
    FOREIGN KEY (id_pasajero) REFERENCES pasajeros(id_pasajero),
    FOREIGN KEY (id_reserva) REFERENCES reservas(id_reserva)
);

-- =====================================================
-- MÓDULO 29: INTEROPERABILIDAD CON OACI (7 TABLAS)
-- =====================================================

-- Tabla 29.1: codigos_oaci_paises
CREATE TABLE codigos_oaci_paises (
    id_pais_oaci NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre_pais VARCHAR2(50) NOT NULL,
    codigo_oaci_pais VARCHAR2(2) NOT NULL UNIQUE,
    rango_inicio VARCHAR2(3),
    rango_fin VARCHAR2(3),
    fecha_asignacion DATE,
    observaciones VARCHAR2(500)
);

-- Tabla 29.2: series_vuelo_asignadas
CREATE TABLE series_vuelo_asignadas (
    id_serie_vuelo NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_pais_oaci NUMBER NOT NULL,
    id_aerolinea NUMBER NOT NULL,
    rango_numeros_inicio VARCHAR2(10) NOT NULL,
    rango_numeros_fin VARCHAR2(10) NOT NULL,
    fecha_asignacion DATE DEFAULT SYSDATE,
    fecha_vencimiento DATE,
    activa NUMBER(1) DEFAULT 1,
    documento_asignacion BLOB,
    FOREIGN KEY (id_pais_oaci) REFERENCES codigos_oaci_paises(id_pais_oaci),
    FOREIGN KEY (id_aerolinea) REFERENCES aerolineas(id_aerolinea)
);

-- Tabla 29.3: reportes_oaci
CREATE TABLE reportes_oaci (
    id_reporte_oaci NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    tipo_reporte VARCHAR2(30) CHECK (tipo_reporte IN ('ESTADISTICO', 'SEGURIDAD', 'OPERACIONES', 'INCIDENTES', 'FINANCIERO')),
    periodo VARCHAR2(20) CHECK (periodo IN ('MENSUAL', 'TRIMESTRAL', 'SEMESTRAL', 'ANUAL')),
    fecha_inicio_periodo DATE NOT NULL,
    fecha_fin_periodo DATE NOT NULL,
    fecha_envio DATE,
    contenido_reporte CLOB,
    archivo_reporte BLOB,
    estado VARCHAR2(20) DEFAULT 'GENERADO' CHECK (estado IN ('GENERADO', 'ENVIADO', 'RECIBIDO', 'RECHAZADO')),
    enviado_por NUMBER,
    confirmacion_recibido NUMBER(1) DEFAULT 0,
    observaciones VARCHAR2(500),
    FOREIGN KEY (enviado_por) REFERENCES empleados(id_empleado)
);

-- Tabla 29.4: estandares_internacionales
CREATE TABLE estandares_internacionales (
    id_estandar NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    codigo_estandar VARCHAR2(30) UNIQUE NOT NULL,
    nombre_estandar VARCHAR2(200) NOT NULL,
    descripcion CLOB,
    organismo_emisor VARCHAR2(100),
    fecha_publicacion DATE,
    version VARCHAR2(10),
    fecha_vigencia DATE,
    obligatorio NUMBER(1) DEFAULT 1,
    documento_estandar BLOB,
    activo NUMBER(1) DEFAULT 1
);

-- Tabla 29.5: auditorias_internacionales
CREATE TABLE auditorias_internacionales (
    id_auditoria_internacional NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    entidad_auditora VARCHAR2(100) NOT NULL,
    fecha_auditoria DATE NOT NULL,
    tipo_auditoria VARCHAR2(30) CHECK (tipo_auditoria IN ('SEGURIDAD', 'OPERACIONES', 'AMBIENTAL', 'CALIDAD', 'FINANCIERA')),
    alcance CLOB NOT NULL,
    auditores VARCHAR2(500),
    areas_auditadas CLOB,
    hallazgos CLOB,
    no_conformidades CLOB,
    recomendaciones CLOB,
    fecha_informe DATE,
    informe_auditoria BLOB,
    plazo_correccion_dias NUMBER,
    fecha_cierre DATE,
    observaciones VARCHAR2(500)
);

-- Tabla 29.6: certificaciones_internacionales
CREATE TABLE certificaciones_internacionales (
    id_certificacion_internacional NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_estandar NUMBER,
    nombre_certificacion VARCHAR2(200) NOT NULL,
    organismo_certificador VARCHAR2(100) NOT NULL,
    fecha_emision DATE NOT NULL,
    fecha_vencimiento DATE,
    alcance_certificacion CLOB,
    numero_certificado VARCHAR2(50) UNIQUE NOT NULL,
    documento_certificado BLOB,
    activa NUMBER(1) DEFAULT 1,
    responsable_seguimiento NUMBER,
    FOREIGN KEY (id_estandar) REFERENCES estandares_internacionales(id_estandar),
    FOREIGN KEY (responsable_seguimiento) REFERENCES empleados(id_empleado)
);

-- Tabla 29.7: notificaciones_oaci
CREATE TABLE notificaciones_oaci (
    id_notificacion_oaci NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    numero_notificacion VARCHAR2(30) UNIQUE NOT NULL,
    fecha_recepcion TIMESTAMP DEFAULT SYSTIMESTAMP,
    tipo_notificacion VARCHAR2(30) CHECK (tipo_notificacion IN ('CIRCULAR', 'DIRECTIVA', 'REQUERIMIENTO', 'INFORMACION', 'ALERTA')),
    asunto VARCHAR2(300) NOT NULL,
    descripcion CLOB,
    fecha_limite_cumplimiento DATE,
    documento_notificacion BLOB,
    area_responsable NUMBER,
    estado_cumplimiento VARCHAR2(30) DEFAULT 'PENDIENTE' CHECK (estado_cumplimiento IN ('PENDIENTE', 'EN_PROCESO', 'CUMPLIDO', 'VENCIDO')),
    fecha_cumplimiento DATE,
    observaciones VARCHAR2(500),
    FOREIGN KEY (area_responsable) REFERENCES departamentos(id_departamento)
);

-- =====================================================
-- MÓDULO 6: TRIPULACIÓN (COMPLETAR TABLAS PENDIENTES)
-- =====================================================

-- Tabla 6.2: vuelos_tripulacion (clave compuesta)
CREATE TABLE vuelos_tripulacion (
    id_vuelo NUMBER,
    id_tripulante NUMBER,
    rol_asignado VARCHAR2(30),
    horas_trabajadas NUMBER,
    observaciones VARCHAR2(200),
    PRIMARY KEY (id_vuelo, id_tripulante),
    FOREIGN KEY (id_vuelo) REFERENCES vuelos(id_vuelo),
    FOREIGN KEY (id_tripulante) REFERENCES tripulacion(id_tripulante)
);

-- =====================================================
-- MÓDULO 7: PASAJEROS (COMPLETAR TABLA PENDIENTE)
-- =====================================================

-- Tabla 7.6: pasajeros_historial
CREATE TABLE pasajeros_historial (
    id_historial_pasajero NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_pasajero NUMBER,
    id_vuelo NUMBER,
    fecha_vuelo DATE,
    tipo_historial VARCHAR2(30) CHECK (tipo_historial IN ('VUELO', 'INCIDENTE', 'RECLAMO')),
    descripcion VARCHAR2(500),
    fecha_registro TIMESTAMP,
    FOREIGN KEY (id_pasajero) REFERENCES pasajeros(id_pasajero),
    FOREIGN KEY (id_vuelo) REFERENCES vuelos(id_vuelo)
);

